/* Spanish translation of the CWNP CWNA practice questions. Options keep the same order as the English bank. */
CertHub.addQuestionsEs("cwna", {
  "cw1": ["Un ingeniero lee que un access point transmite a 100 mW. ¿Cuál es este nivel de potencia en dBm?", ["10 dBm", "20 dBm", "30 dBm", "100 dBm"], "10 × log10(100) = 20, así que 100 mW equivalen a 20 dBm. 10 dBm serían 10 mW y 30 dBm serían 1,000 mW.", ["10 dBm son 10 mW; 100 mW es diez veces más potencia, lo que suma otros 10 dB.", null, "30 dBm son 1,000 mW (1 W), diez veces más que 100 mW.", "100 dBm confunde el número en mW con dBm; serían 10^10 mW, muy por encima de cualquier radio Wi-Fi."]],
  "cw2": ["Un radio entrega 17 dBm a través de un cable con 2 dB de pérdida hacia una antena de 6 dBi. ¿Cuál es el EIRP?", ["23 dBm", "25 dBm", "19 dBm", "21 dBm"], "EIRP = 17 − 2 + 6 = 21 dBm. Sumar la pérdida del cable en lugar de restarla da el tentador 25 dBm.", ["23 dBm ignora los 2 dB de pérdida del cable y simplemente suma la potencia de salida y la ganancia de la antena.", "25 dBm suma la pérdida de 2 dB del cable en lugar de restarla; las pérdidas siempre reducen la potencia que llega a la antena.", "19 dBm resta la pérdida del cable pero olvida sumar la ganancia de 6 dBi de la antena, que aumenta la potencia radiada.", null]],
  "cw3": ["Una laptop reporta una señal recibida de −65 dBm y un piso de ruido de −92 dBm. ¿Cuál es la SNR?", ["27 dB", "157 dB", "−27 dB", "92 dB"], "La SNR es la señal menos el ruido: −65 − (−92) = 27 dB. Sumar los valores absolutos da el erróneo 157.", [null, "157 dB suma los valores absolutos de la señal y el ruido; la SNR es la diferencia entre ambos, no la suma.", "Una SNR negativa significaría que el ruido es más fuerte que la señal; aquí la señal de -65 dBm está 27 dB por encima del piso de ruido de -92 dBm.", "92 dB es solo el valor del piso de ruido sin su signo; la SNR debe comparar la señal contra ese ruido."]],
  "cw4": ["A un transmisor de 40 mW se le agregan 3 dB de ganancia en su salida. ¿Aproximadamente cuánta potencia resulta?", ["120 mW", "43 mW", "80 mW", "400 mW"], "Cada 3 dB de ganancia duplican aproximadamente la potencia, así que 40 mW pasan a ser unos 80 mW. 10 dB de ganancia darían 400 mW.", ["120 mW sería triplicar la potencia; 3 dB de ganancia aproximadamente duplican la potencia en lugar de multiplicarla por tres.", "43 mW suma el valor de 3 dB directamente a la cifra en milivatios; los decibelios son relaciones, no milivatios que se suman.", null, "400 mW es un aumento de diez veces, que es lo que dan 10 dB de ganancia, no 3 dB."]],
  "cw5": ["¿Qué afirmación sobre las señales de 2.4 GHz y 5 GHz es correcta?", ["Ambas bandas comparten una misma longitud de onda", "2.4 GHz tiene la longitud de onda más corta", "5 GHz tiene la longitud de onda más corta", "La longitud de onda depende de la potencia de transmisión"], "La longitud de onda es inversamente proporcional a la frecuencia, así que la banda más alta de 5 GHz tiene la longitud de onda más corta (unos 6 cm frente a 12.5 cm). La potencia cambia la amplitud, no la longitud de onda.", ["La longitud de onda depende de la frecuencia, así que dos bandas en frecuencias distintas no pueden compartir una misma longitud de onda.", "Es al revés: 2.4 GHz es la frecuencia más baja, así que tiene la longitud de onda más larga (unos 12.5 cm).", null, "La potencia de transmisión cambia la amplitud de la onda, no su longitud de onda, que está determinada por la frecuencia."]],
  "cw6": ["En un almacén lleno de estanterías metálicas, un cliente recibe varias copias retrasadas de la misma transmisión. ¿Qué comportamiento de RF causa principalmente esto?", ["Reflexión", "Absorción", "Refracción", "Pérdida de trayectoria en espacio libre"], "Las superficies metálicas reflejan la RF y crean múltiples trayectorias que llegan en momentos distintos (multipath). La absorción debilita la señal, pero no crea copias.", [null, "La absorción convierte la energía de RF en calor y debilita la señal, pero no produce copias retrasadas de ella.", "La refracción desvía una onda cuando pasa entre medios de distinta densidad; no explica muchos ecos en estanterías metálicas.", "La pérdida de trayectoria en espacio libre es el debilitamiento por la dispersión de la onda con la distancia y no crea múltiples copias."]],
  "cw7": ["La señal en un auditorio es fuerte cuando está vacío, pero cae bruscamente cuando se llena de estudiantes. ¿Qué comportamiento lo explica?", ["Dispersión (scattering)", "Difracción", "Reflexión", "Absorción"], "El cuerpo humano es mayormente agua, que absorbe la energía de RF y la convierte en calor. La difracción es la desviación alrededor de bordes, no la pérdida dentro de un material.", ["La dispersión ocurre en superficies rugosas o irregulares y en objetos pequeños; no explica la energía perdida en una multitud de cuerpos llenos de agua.", "La difracción es la desviación alrededor del borde de un obstáculo; aquí la pérdida ocurre dentro de las propias personas.", "La reflexión hace rebotar las señales en superficies lisas como metal o vidrio; los cuerpos humanos mayormente absorben la energía de 2.4 y 5 GHz en lugar de reflejarla.", null]],
  "cw8": ["Los usuarios que están justo detrás de la esquina de un muro grueso de concreto aún reciben una señal débil, aunque el muro bloquea la trayectoria directa. ¿Qué comportamiento permite que la señal les llegue?", ["Absorción en el muro", "Difracción alrededor del borde del muro", "Refracción a través del aire", "Polarización de la señal"], "La difracción desvía una onda alrededor del borde de un obstáculo y deja detrás una sombra de RF más débil. La absorción solo elimina energía.", ["La absorción solo elimina energía dentro del muro; no puede redirigir la señal alrededor de la esquina hacia los usuarios.", null, "La refracción es la desviación de una onda al pasar por medios de distinta densidad, como capas de aire o vidrio, no la desviación alrededor del borde de un muro.", "La polarización es la orientación del campo eléctrico; no permite que una señal rodee una obstrucción."]],
  "cw9": ["Un enlace puente exterior con una trayectoria completamente despejada sigue mostrando menor señal recibida a medida que aumenta la distancia. ¿Cuál es la razón principal?", ["El VSWR del cable aumenta con la distancia", "El vapor de agua absorbe la mayor parte de la energía de 5 GHz", "El multipath siempre cancela la señal principal", "El frente de onda se dispersa con la distancia"], "La pérdida de trayectoria en espacio libre se debe a que la onda se dispersa sobre un área mayor a medida que viaja, incluso sin obstáculos. Los efectos del clima son menores a estas distancias y el VSWR no depende de la longitud del enlace.", ["El VSWR refleja un desajuste de impedancia en el cable y los conectores, que no cambia cuando el enlace se hace más largo.", "El vapor de agua causa solo una atenuación menor a 5 GHz en las distancias típicas de un puente; no es la causa principal de esta pérdida.", "El multipath puede causar desvanecimiento, pero no siempre cancela la señal y una trayectoria exterior despejada tiene poco; no explica una caída constante con la distancia.", null]],
  "cw10": ["Se instaló un enlace punto a punto con una Yagi montada verticalmente y la otra horizontalmente. ¿Cuál es el resultado probable?", ["Mayor ganancia por diversidad de polarización", "Gran pérdida por desajuste de polarización", "Ningún efecto, ya que las Yagi son omnidireccionales", "Un ancho de haz mayor en ambas antenas"], "Las antenas de un enlace deben compartir la misma polarización; un desajuste de 90 grados causa una gran pérdida de señal. Las Yagi son semidireccionales, no omnidireccionales.", ["La diversidad de polarización es un diseño multiantena deliberado; desalinear los dos extremos de un enlace pierde señal en lugar de agregar ganancia.", null, "Las Yagi son antenas semidireccionales, así que la premisa es incorrecta y la polarización sigue importando.", "Rotar una antena cambia su polarización, no su ancho de haz; el patrón del haz no cambia, pero el enlace sufre pérdida por desajuste."]],
  "cw11": ["Dos edificios pueden ver las antenas en la azotea del otro, pero unos árboles invaden el área justo debajo de la trayectoria visual y el enlace es inestable. ¿Qué debe atender el ingeniero?", ["El plano de tierra bajo el mástil", "El lóbulo trasero de las antenas", "El despeje de la zona de Fresnel", "Solo el ancho de haz horizontal"], "La línea de vista de RF requiere que la mayor parte de la primera zona de Fresnel esté despejada, no solo una trayectoria visual. Las obstrucciones dentro de ella reducen y desestabilizan la señal.", ["Un plano de tierra afecta los patrones de algunos tipos de antena, pero el problema aquí son los árboles que invaden la trayectoria cerca de la línea de vista.", "El lóbulo trasero es la energía radiada detrás de la antena; no explica una obstrucción entre los dos edificios.", null, "El ancho de haz horizontal describe el ancho de cobertura de la antena; los árboles están bloqueando la zona de Fresnel, lo que no se corrige cambiando el ancho de haz."]],
  "cw12": ["Una empresa necesita un enlace de alta ganancia y haz estrecho entre dos sitios separados por varios kilómetros. ¿Qué tipo de antena es el MÁS adecuado?", ["Plato parabólico", "Dipolo omnidireccional", "Antena patch de techo para interiores", "Sectorial de gran ángulo"], "Los platos parabólicos, altamente direccionales, ofrecen la mayor ganancia y el haz más estrecho para enlaces punto a punto largos. Las omnidireccionales y las sectoriales distribuyen la energía sobre áreas amplias.", [null, "Un dipolo omnidireccional distribuye la energía en todas direcciones con baja ganancia, lo que es inadecuado para un enlace punto a punto de varios kilómetros.", "Una antena patch de techo para interiores está pensada para cobertura interior y tiene ganancia modesta; no está diseñada para enlaces exteriores largos.", "Una antena sectorial cubre un arco amplio para servicio punto a multipunto, así que su ganancia y su haz son demasiado amplios para un enlace único largo."]],
  "cw13": ["La hoja de datos de una antena indica una ganancia de 5 dBd. ¿Cuál es la ganancia equivalente en dBi?", ["2.86 dBi", "7.14 dBi", "5 dBi", "10 dBi"], "Un dipolo tiene 2.14 dBi de ganancia, así que dBi = dBd + 2.14 = 7.14 dBi. Restar en lugar de sumar da 2.86.", ["2.86 dBi resta la ganancia de 2.14 dB del dipolo; convertir dBd a dBi significa sumarla porque dBi usa una referencia más baja.", null, "5 dBi trataría dBd y dBi como la misma unidad, ignorando la ganancia de 2.14 dB de la referencia del dipolo.", "10 dBi duplica el número en lugar de sumar el desfase fijo de 2.14 dB entre las dos referencias."]],
  "cw14": ["El radio de un AP se describe como 3x3:2. ¿Qué significa esto?", ["3 spatial streams y 2 cadenas de recepción", "3 streams, 3 antenas, 2 bandas", "3 radios por banda y 2 bandas en total", "3 cadenas de transmisión, 3 cadenas de recepción, 2 streams"], "La notación MIMO es cadenas de transmisión × cadenas de recepción : spatial streams. El radio puede enviar dos streams mientras usa las tres cadenas para diversidad.", ["La notación MIMO indica primero las cadenas de transmisión, luego las de recepción y luego los streams, así que 3x3:2 tiene dos spatial streams, no tres.", "La notación no dice nada sobre bandas ni cantidad de antenas; el número después de los dos puntos son los spatial streams.", "3x3:2 describe las cadenas de radio y los streams de un solo radio, no la cantidad de radios ni de bandas.", null]],
  "cw15": ["¿Qué organización redacta y publica el estándar 802.11 y sus enmiendas?", ["IEEE", "Wi-Fi Alliance", "IETF", "FCC"], "El IEEE mantiene el 802.11. La Wi-Fi Alliance certifica la interoperabilidad, el IETF redacta protocolos de internet como RADIUS y la FCC regula el espectro en EE. UU.", [null, "La Wi-Fi Alliance certifica la interoperabilidad y nombra las generaciones, pero no redacta el estándar 802.11.", "El IETF redacta protocolos de internet como RADIUS e IP, no el estándar de LAN inalámbrica 802.11.", "La FCC regula el uso del espectro en Estados Unidos; no redacta estándares técnicos como el 802.11."]],
  "cw16": ["Un comprador quiere asegurarse de que un nuevo adaptador cliente funcionará con WPA3 en access points de otros fabricantes. ¿Qué debe buscar?", ["Autorización de equipo de la FCC para el adaptador", "Ratificación IEEE 802.11 del adaptador", "Wi-Fi CERTIFIED WPA3 de la Wi-Fi Alliance", "Un número de RFC del IETF en la caja del producto"], "La Wi-Fi Alliance prueba los productos en cuanto a interoperabilidad y funciones de seguridad como WPA3. La autorización de la FCC cubre las emisiones, no la interoperabilidad.", ["La autorización de equipo de la FCC cubre las emisiones y la operación legal, no si WPA3 interopera con otros fabricantes.", "El IEEE ratifica estándares, no productos individuales, y no prueba la interoperabilidad.", null, "Los RFC del IETF definen protocolos de internet; no son certificaciones de producto y no dicen nada sobre la interoperabilidad de WPA3."]],
  "cw17": ["¿Quién decide qué canales y qué potencia máxima de transmisión puede usar legalmente un AP en un país determinado?", ["La Wi-Fi Alliance", "El grupo de trabajo IEEE 802.11", "La autoridad reguladora de ese país", "El fabricante del AP"], "Los reguladores nacionales, como la FCC en Estados Unidos, fijan las frecuencias legales y los límites de potencia. El IEEE define cómo funciona el protocolo dentro de esas reglas.", ["La Wi-Fi Alliance certifica productos, pero no tiene autoridad legal sobre canales ni potencia en ningún país.", "El grupo de trabajo IEEE 802.11 define cómo funciona el protocolo, pero el regulador de cada país decide qué es legal usar.", null, "El fabricante debe construir productos que cumplan las reglas locales, pero no establece esas reglas."]],
  "cw18": ["Un ingeniero planifica canales de 20 MHz en 2.4 GHz para una oficina en Norteamérica. ¿Qué conjunto evita la superposición?", ["1, 6 y 11", "1, 5 y 9", "2, 7 y 12", "1, 4, 8 y 11"], "Los canales de 2.4 GHz están separados 5 MHz, pero tienen unos 20 MHz de ancho, así que 1, 6 y 11 son el conjunto estándar sin superposición en Norteamérica.", [null, "Los canales 1, 5 y 9 están separados solo 20 MHz en su frecuencia central, así que sus señales de unos 22 MHz de ancho aún se superponen un poco y no es el plan estándar.", "2, 7 y 12 tiene la separación correcta, pero el canal 12 no se puede usar a potencia normal en Norteamérica, así que no es el plan estándar allí.", "Cuatro canales en 1, 4, 8 y 11 están separados solo por tres canales, así que los adyacentes se superponen mucho."]],
  "cw19": ["¿Qué enmienda 802.11 introdujo OFDMA y BSS coloring?", ["802.11g", "802.11ac", "802.11n", "802.11ax"], "802.11ax (HE, Wi-Fi 6) agregó OFDMA, BSS coloring, Target Wake Time y 1024-QAM. 802.11ac introdujo MU-MIMO de bajada, pero no OFDMA.", ["802.11g llevó OFDM a 2.4 GHz con hasta 54 Mbps; no tiene OFDMA ni BSS coloring.", "802.11ac agregó canales más anchos, 256-QAM y MU-MIMO de bajada, pero OFDMA y BSS coloring llegaron después con 802.11ax.", "802.11n introdujo MIMO y canales de 40 MHz, no OFDMA ni BSS coloring.", null]],
  "cw20": ["La hoja de datos de un cliente indica solo tasas VHT (802.11ac). ¿En qué banda puede usar esas tasas?", ["Solo 2.4 GHz", "Solo 5 GHz", "2.4 y 5 GHz", "Solo 6 GHz"], "VHT de 802.11ac está definido solo para 5 GHz. 802.11ax (HE) funciona en 2.4, 5 y 6 GHz, que es la confusión tentadora.", ["VHT no está definido para 2.4 GHz; un dispositivo solo de 2.4 GHz usaría HT o tasas más antiguas.", null, "Las tasas VHT de 802.11ac son solo para 5 GHz; en 2.4 GHz el cliente recurre a HT (802.11n) o tasas más antiguas.", "El Wi-Fi de 6 GHz usa HE (802.11ax) o más reciente; los clientes VHT no pueden operar en 6 GHz en absoluto."]],
  "cw21": ["¿Qué enmienda introdujo por primera vez MIMO y canales de 40 MHz bajo el nombre HT?", ["802.11ac", "802.11a", "802.11g", "802.11n"], "802.11n (High Throughput, Wi-Fi 4) agregó MIMO y canales de 40 MHz. Más tarde, 802.11ac agregó 80 y 160 MHz.", ["802.11ac (VHT) amplió MIMO con canales de 80/160 MHz y MU-MIMO; no introdujo HT.", "802.11a introdujo OFDM en 5 GHz con un solo stream y canales de 20 MHz, sin MIMO.", "802.11g llevó ERP-OFDM a 2.4 GHz con canales de 20 MHz de un solo stream, no MIMO.", null]],
  "cw22": ["Un escáner de códigos de barras antiguo solo soporta 1, 2, 5.5 y 11 Mbps. ¿Qué PHY usa?", ["ERP-OFDM (802.11g)", "HR/DSSS (802.11b)", "OFDM (802.11a)", "HT (802.11n)"], "Esas cuatro tasas son las tasas DSSS y HR/DSSS de 802.11b. Las tasas de ERP-OFDM y OFDM comienzan en 6 Mbps.", ["ERP-OFDM (802.11g) usa tasas OFDM de 6 a 54 Mbps; solo 1-11 Mbps indicaría DSSS/HR-DSSS.", null, "OFDM de 802.11a funciona a 6-54 Mbps en 5 GHz y nunca usa 1, 2, 5.5 u 11 Mbps.", "HT (802.11n) usa tasas basadas en MCS que comienzan en 6.5 Mbps; un dispositivo limitado a 1-11 Mbps es 802.11b."]],
  "cw23": ["Un administrador quiere agregar un radio de 6 GHz a un SSID existente con WPA2-Personal. ¿Cuál es el problema?", ["6 GHz necesita protección para 802.11b", "6 GHz permite solo canales de 20 MHz", "6 GHz necesita WPA3 o Enhanced Open", "6 GHz no puede usar ninguna passphrase"], "Las reglas de Wi-Fi 6E exigen WPA3 (SAE o Enterprise) u OWE con PMF en 6 GHz; WPA2 no está permitido. 6 GHz soporta canales anchos y WPA3-Personal usa una passphrase.", ["802.11b no existe en 6 GHz y no se necesita ningún mecanismo de protección para él allí.", "6 GHz soporta 20, 40, 80 y 160 MHz (y 320 MHz con Wi-Fi 7), así que el ancho de canal no es el problema.", null, "WPA3-Personal (SAE) sigue usando una passphrase en 6 GHz; solo el método PSK de WPA2-Personal no está permitido."]],
  "cw24": ["Un AP en el canal 100 de 5 GHz cambia de canal repentinamente y los clientes se desconectan brevemente. El log muestra un evento de radar. ¿Qué requisito causó esto?", ["Dynamic Frequency Selection", "Transmit Power Control", "Clear Channel Assessment", "Selección automática de tasa"], "DFS exige que los dispositivos en canales compartidos con radares los abandonen cuando se detecta un radar. TPC controla los niveles de potencia, no los cambios de canal tras un radar.", [null, "TPC reduce la potencia de transmisión para disminuir la interferencia; no obliga a cambiar de canal tras detectar un radar.", "CCA es la forma en que una estación detecta si el medio está ocupado antes de transmitir; no es un requisito regulatorio sobre radares.", "La selección de tasa cambia las tasas de datos según la calidad de la señal, no el canal tras un evento de radar."]],
  "cw25": ["¿Por qué los clientes en el borde de una celda 802.11ax nunca alcanzan las tasas de datos de 1024-QAM?", ["1024-QAM solo funciona en 2.4 GHz", "1024-QAM necesita una SNR muy alta cerca del AP", "1024-QAM está limitado a clientes legacy", "1024-QAM se desactiva siempre que DFS está activo"], "Una modulación más densa empaqueta más bits por símbolo, pero necesita una señal limpia y fuerte. Lejos del AP, la SNR baja y la tasa cambia a una modulación más simple.", ["1024-QAM es parte de 802.11ax y se puede usar en 2.4, 5 y 6 GHz, así que la banda no es la razón.", null, "Los clientes legacy no pueden usar 1024-QAM en absoluto; requiere dispositivos compatibles con 802.11ax (HE).", "DFS rige la detección de radares en ciertos canales de 5 GHz y no desactiva ningún tipo de modulación."]],
  "cw26": ["Una oficina densa quiere canales de 40 MHz en 2.4 GHz para tener más velocidad. ¿Cuál es el MEJOR consejo?", ["Evitarlo: 40 MHz solo existe en 6 GHz", "Usarlo: 2.4 GHz tiene cuatro canales limpios de 40 MHz", "Usarlo: el bonding elimina la contención cocanal", "Evitarlo: solo cabe un canal limpio de 40 MHz"], "La banda de 2.4 GHz es demasiado estrecha para más de un canal de 40 MHz sin superposición, así que hacer bonding allí causa una gran superposición. 40 MHz es común en 5 GHz.", ["Los canales de 40 MHz fueron introducidos por 802.11n y se usan ampliamente en 5 GHz; no están limitados a 6 GHz.", "La banda de 2.4 GHz tiene solo unos 83.5 MHz de ancho, así que no puede contener cuatro canales limpios de 40 MHz.", "El channel bonding hace cada canal más ancho y deja menos canales sin superposición, lo que aumenta la contención cocanal.", null]],
  "cw27": ["¿Qué enmienda define la fast BSS transition para que los clientes 802.1X puedan hacer roaming sin una reautenticación completa?", ["802.11r", "802.11k", "802.11v", "802.11w"], "802.11r (FT) deriva las claves por adelantado para el AP de destino. 802.11k entrega neighbor reports y 802.11w protege las tramas de gestión.", [null, "802.11k proporciona mediciones de radio y neighbor reports para ayudar a elegir un AP de destino, pero no acelera el intercambio de claves.", "802.11v proporciona BSS transition management y otras sugerencias de la red; no define la derivación rápida de claves para el roaming.", "802.11w protege tramas de gestión como la desautenticación; no tiene nada que ver con el roaming rápido."]],
  "cw28": ["Un cliente le pide a su AP una lista de los AP cercanos para acelerar el roaming. ¿Qué enmienda proporciona este neighbor report?", ["802.11w", "802.11r", "802.11k", "802.11e"], "La medición de recursos de radio de 802.11k incluye los neighbor reports. 802.11r acelera el intercambio de claves una vez elegido el destino.", ["802.11w define las tramas de gestión protegidas, no los neighbor reports.", "802.11r acelera la autenticación y el intercambio de claves durante un roaming, pero no proporciona la lista de AP cercanos.", null, "802.11e define QoS (EDCA), que prioriza clases de tráfico en lugar de informar sobre AP vecinos."]],
  "cw29": ["Una hoja de especificaciones dice que el AP soporta Wi-Fi 5. ¿Qué enmienda es esa?", ["802.11n", "802.11ax", "802.11ac", "802.11be"], "Los nombres de la Wi-Fi Alliance son Wi-Fi 4 (n), Wi-Fi 5 (ac), Wi-Fi 6/6E (ax) y Wi-Fi 7 (be).", ["802.11n es Wi-Fi 4 según los nombres de generación de la Wi-Fi Alliance.", "802.11ax es Wi-Fi 6 (y Wi-Fi 6E en la banda de 6 GHz).", null, "802.11be es Wi-Fi 7, dos generaciones después de Wi-Fi 5."]],
  "cw30": ["¿Qué lista muestra canales de 20 MHz adyacentes y sin superposición en la banda U-NII-1 de 5 GHz?", ["36, 40, 44, 48", "1, 6, 11, 14", "36, 38, 40, 42", "100, 101, 102, 103"], "Los números de canal de 5 GHz están separados 5 MHz, así que los canales de 20 MHz avanzan de cuatro en cuatro: 36, 40, 44 y 48 en U-NII-1.", [null, "1, 6, 11 y 14 son canales de 2.4 GHz, y el 14 solo está permitido en Japón para 802.11b; ninguno está en U-NII-1.", "Los canales 38 y 42 son los números centrales usados para canales agrupados de 40 y 80 MHz, así que esta lista mezcla anchos y se superpone.", "Los números de canal de 5 GHz están separados 5 MHz, así que 100, 101, 102 y 103 se superpondrían casi por completo y no son canales válidos de 20 MHz."]],
  "cw31": ["¿Qué le permite hacer OFDMA a un AP 802.11ax?", ["Transmitir en el canal 14 de 2.4 GHz en todas las regiones", "Unir dos bandas separadas en un solo canal ancho", "Cifrar tramas sin ningún 4-way handshake", "Atender a varios clientes a la vez usando resource units"], "OFDMA divide un canal en resource units para que varios clientes puedan ser atendidos en una sola transmisión, lo que reduce la sobrecarga en tramas pequeñas.", ["El canal 14 solo está permitido en Japón y solo para 802.11b; OFDMA no cambia las reglas regionales de canales.", "Combinar bandas separadas no es OFDMA; eso se relaciona con la operación multienlace (multi-link operation) de Wi-Fi 7, mientras que OFDMA subdivide un solo canal.", "OFDMA es un método de acceso múltiple, no de cifrado; las tramas siguen protegidas con claves del 4-way handshake.", null]],
  "cw32": ["Unos sensores IoT a batería en una red 802.11ax necesitan mayor duración de batería. ¿Qué función permite al AP programar cuándo se despiertan?", ["BSS coloring", "Target Wake Time", "MU-MIMO", "Transmit beamforming"], "TWT permite que el AP y el cliente acuerden horarios de activación para que el radio pueda dormir más tiempo. BSS coloring ayuda con la reutilización espacial, no con el ahorro de energía.", ["BSS coloring etiqueta las tramas de cada BSS para mejorar la reutilización espacial en celdas superpuestas; no programa los tiempos de activación de los clientes.", null, "MU-MIMO envía spatial streams separados a varios clientes a la vez para mejorar la capacidad, no la duración de la batería.", "El transmit beamforming concentra la energía hacia un cliente para mejorar la señal; no permite que un cliente duerma más tiempo."]],
  "cw33": ["Una captura muestra tramas beacon cada 102.4 ms. ¿Qué tipo de trama 802.11 es un beacon?", ["Null function", "Control", "Datos", "Gestión"], "Los beacons, probes y las tramas de autenticación y asociación son tramas de gestión. Null function es un subtipo de datos.", ["Null function es un subtipo de trama de datos sin payload, que se usa a menudo para señalar el estado de ahorro de energía; los beacons no son tramas null.", "Las tramas de control como ACK, RTS y CTS ayudan a entregar otras tramas; los beacons anuncian el BSS y son tramas de gestión.", "Las tramas de datos transportan el payload del usuario (o datos null); un beacon transporta información del BSS, no datos de usuario.", null]],
  "cw34": ["¿Qué tipo de trama 802.11 incluye las tramas ACK, RTS y CTS?", ["Gestión", "Control", "Datos", "Action"], "ACK, RTS, CTS y Block Ack son tramas de control que ayudan a entregar otras tramas. Las tramas Action son un subtipo de gestión.", ["Las tramas de gestión incluyen beacons, probes, autenticación y asociación, no ACK, RTS ni CTS.", null, "Las tramas de datos transportan payload; ACK, RTS y CTS no llevan datos de usuario y ayudan en la entrega.", "Las tramas Action son un subtipo de trama de gestión que se usa para cosas como configurar Block Ack y solicitudes 802.11k/v, no un tipo de trama separado."]],
  "cw35": ["¿Cuál es el orden correcto de las tramas cuando un cliente se une a un BSS con WPA2-Personal?", ["Autenticación, probe, 4-way handshake, asociación", "Probe, asociación, 4-way handshake, autenticación", "Probe, autenticación, asociación, 4-way handshake", "4-way handshake, probe, autenticación, asociación"], "El cliente descubre el BSS, realiza la autenticación de sistema abierto, se asocia y luego ejecuta el 4-way handshake para derivar las claves.", ["El cliente no puede autenticarse antes de descubrir el BSS, y la asociación debe ocurrir antes del 4-way handshake.", "La autenticación de sistema abierto ocurre antes de la asociación, no después del 4-way handshake.", null, "El 4-way handshake necesita una asociación establecida primero, así que no puede ocurrir antes del probing."]],
  "cw36": ["Una captura muestra una laptop enviando probe requests en cada canal por turnos. ¿Qué está haciendo la laptop?", ["Escaneo activo", "Escaneo pasivo", "Reasociándose", "Desautenticándose"], "El escaneo activo consiste en enviar probe requests y esperar probe responses. El escaneo pasivo solo escucha los beacons.", [null, "El escaneo pasivo consiste en escuchar beacons sin transmitir; enviar probe requests es escaneo activo.", "La reasociación es una solicitud a un AP específico al hacer roaming dentro de un ESS, no probes enviados en cada canal por turnos.", "La desautenticación termina una conexión existente y no se envía en cada canal para descubrir redes."]],
  "cw37": ["Una estación escucha una trama cuyo campo Duration es de 300 µs y se abstiene de transmitir durante ese tiempo. ¿Qué mecanismo es este?", ["CCA por detección de energía", "Detección virtual de portadora (NAV)", "El temporizador de backoff aleatorio", "El intervalo SIFS"], "El temporizador NAV se fija a partir del campo Duration de las tramas escuchadas, así que la estación difiere aunque después no detecte energía. CCA es la detección física de portadora.", ["El CCA por detección de energía es la detección física de portadora, que reacciona a la energía presente en el canal, no un temporizador fijado a partir de un campo Duration.", null, "El temporizador de backoff aleatorio se toma de la ventana de contención después de que el medio queda libre; no lo fija el campo Duration de otra estación.", "SIFS es un intervalo fijo y muy corto antes de respuestas como los ACK, no una espera de 300 µs tomada de una trama escuchada."]],
  "cw38": ["¿Qué logra un intercambio RTS/CTS antes de enviar una trama de datos?", ["Verifica el estado de ahorro de energía del cliente", "Cifra la siguiente trama de datos", "Le pide al AP una tasa de datos más alta", "Reserva el medio mediante el NAV"], "El CTS del AP fija el NAV de todas las estaciones que lo escuchan, incluidas las estaciones ocultas que no escucharon el RTS, para que difieran.", ["El estado de ahorro de energía se señala con el bit de power management, PS-Poll o tramas null, no con RTS/CTS.", "RTS/CTS no transportan claves ni cifran nada; el cifrado usa las claves del 4-way handshake.", "La selección de tasa la maneja el algoritmo de adaptación de tasa del transmisor; RTS/CTS no negocia tasas de datos.", null]],
  "cw39": ["¿Qué espacio entre tramas es el más corto y se usa antes de un ACK?", ["SIFS", "DIFS", "AIFS", "EIFS"], "SIFS es el intervalo más corto, lo que da prioridad a las tramas ACK y CTS. DIFS y AIFS son más largos y se usan para la contención; EIFS sigue a una trama corrupta.", [null, "DIFS es más largo que SIFS y lo usan las estaciones que compiten por el medio bajo DCF, no antes de un ACK.", "AIFS varía según la categoría de acceso de WMM y se usa para la contención, así que es más largo que SIFS.", "EIFS es una espera extendida que se usa después de recibir una trama corrupta, lo que lo convierte en el más largo de estos espacios."]],
  "cw40": ["Con WMM habilitado, las tramas de voz salen al aire antes que las de best-effort. ¿Por qué?", ["Mayor potencia de transmisión para la voz", "Un canal dedicado solo a voz", "AIFS más cortos y ventanas de contención más pequeñas", "Un espacio garantizado en cada beacon"], "EDCA da a la categoría de acceso de voz un AIFS más corto y una ventana de contención más pequeña, así que normalmente gana la contención. WMM no reserva canales ni espacios.", ["WMM no cambia la potencia de transmisión según la categoría de acceso; la prioridad proviene de los tiempos de contención.", "WMM no reserva un canal separado para la voz; todas las categorías de acceso comparten el mismo canal.", null, "EDCA se basa en contención; los beacons no reservan espacios de transmisión garantizados para las tramas de voz."]],
  "cw41": ["Un teléfono en modo doze se despierta para un beacon y se entera de que el AP tiene tramas unicast guardadas para él. ¿Qué campo del beacon se lo indicó?", ["El DS parameter set", "El elemento SSID", "El Traffic Indication Map", "El elemento de tasas soportadas"], "El TIM enumera los association IDs con tramas unicast en buffer. El DS parameter set indica el canal y el elemento SSID nombra la red.", ["El elemento DS parameter set indica a las estaciones el canal actual del AP, no si hay tramas en buffer.", "El elemento SSID lleva el nombre de la red y no tiene nada que ver con las tramas en buffer.", null, "El elemento de tasas soportadas enumera las tasas de datos que soporta el BSS, no el tráfico en buffer."]],
  "cw42": ["Unos badges push-to-talk en una WLAN tienen grandes retrasos en la voz multicast después de que el administrador aumentó el intervalo DTIM para ahorrar batería. ¿Qué lo explica?", ["Las tramas de grupo esperan al siguiente beacon DTIM", "El TIM deja de enumerar las tramas unicast", "El AP descarta el multicast de los clientes dormidos", "Un DTIM mayor obliga a una tasa de datos más baja"], "El AP guarda en buffer el broadcast y el multicast hasta un beacon DTIM, así que un intervalo DTIM mayor ahorra energía pero agrega retraso al tráfico de grupo.", [null, "El TIM sigue enumerando a los clientes con tramas unicast en buffer en cada beacon, sin importar el intervalo DTIM.", "El AP guarda en buffer el tráfico de grupo para los clientes en modo doze y lo libera después de un beacon DTIM; no simplemente lo descarta.", "El intervalo DTIM controla cuándo se liberan las tramas de grupo en buffer, no la tasa de datos a la que se envían."]],
  "cw43": ["En una WLAN 802.11, ¿qué dispositivo toma la decisión final de hacer roaming?", ["El servidor RADIUS", "El access point", "El controlador WLAN", "La estación cliente"], "El roaming lo decide el cliente. 802.11v permite que la red sugiera un AP mejor, pero el cliente elige si se mueve y cuándo.", ["El servidor RADIUS autentica a los usuarios y no tiene ningún papel en elegir a qué AP se une un cliente.", "Un AP puede sugerir un cambio con 802.11v o desconectar a un cliente, pero el cliente decide si hace roaming y hacia dónde.", "Un controlador puede influir en el roaming con steering y sugerencias 802.11v, pero la estación toma la decisión final.", null]],
  "cw44": ["¿Qué identificador nombra un único basic service set y normalmente es la dirección MAC del radio de un AP?", ["SSID", "BSSID", "ESSID", "OUI"], "El BSSID es una dirección de 48 bits tipo MAC para un BSS. El SSID es el nombre legible de la red, que puede abarcar muchos BSS.", ["El SSID es el nombre legible de la red, que pueden compartir muchos BSS, no un identificador tipo MAC para un solo BSS.", null, "El ESSID es el nombre de red usado en todo un extended service set de muchos AP, no en un solo BSS.", "Un OUI son los primeros 24 bits de una dirección MAC que identifican al fabricante, no un BSS completo."]],
  "cw45": ["En una WLAN basada en controlador, ¿qué protocolo usan comúnmente los AP lightweight para comunicarse con el controlador?", ["BGP", "LLDP", "STP", "CAPWAP"], "CAPWAP es el protocolo de túnel estándar para el tráfico de control del AP al controlador y, opcionalmente, el de datos. LLDP solo anuncia información de vecinos.", ["BGP es un protocolo de enrutamiento de internet entre sistemas autónomos; no se usa entre los AP y un controlador WLAN.", "LLDP anuncia la identidad y las capacidades del dispositivo a los vecinos conectados directamente; no tuneliza el tráfico de control del AP.", "STP evita bucles de capa 2 en redes conmutadas y no tiene ningún papel en la comunicación entre el AP y el controlador.", null]],
  "cw46": ["Un AP nuevo necesita unos 25 W en el dispositivo, y el switch solo soporta 802.3af. ¿Cuál es el estándar PoE mínimo que debería soportar el switch?", ["802.3af (PoE)", "802.3at (PoE+)", "802.3ab", "802.3u"], "802.3af proporciona como máximo 12.95 W en el dispositivo; 802.3at proporciona hasta 25.5 W. 802.3ab y 802.3u son estándares de velocidad Ethernet, no PoE.", ["802.3af garantiza solo 12.95 W en el dispositivo, muy por debajo de los 25 W que necesita este AP.", null, "802.3ab es el estándar Gigabit Ethernet 1000BASE-T sobre cobre y no entrega energía.", "802.3u es Fast Ethernet (100 Mbps) y no define entrega de energía."]],
  "cw47": ["Una tienda pequeña tiene dos AP, sin controlador y sin cuenta en la nube. Cada AP guarda su propia configuración. ¿Qué tipo de AP son?", ["AP administrados desde la nube", "AP lightweight", "AP autónomos", "AP mesh portal"], "Los AP autónomos contienen los planos de gestión, control y datos y se configuran individualmente. Los AP lightweight necesitan un controlador.", ["Los AP administrados desde la nube se configuran desde un servicio en la nube, y esta tienda no tiene cuenta en la nube.", "Los AP lightweight dependen de un controlador para la configuración y el control, y aquí no hay controlador.", null, "Un AP mesh portal conecta el tráfico de la malla inalámbrica con la red cableada; nada aquí describe una malla."]],
  "cw48": ["Un estacionamiento no tiene cableado en sus niveles superiores. Los AP allí deben reenviar el tráfico de forma inalámbrica a un AP que tiene un uplink cableado. ¿Qué diseño es este?", ["Mesh", "Band steering", "Channel bonding", "Balanceo de carga"], "En una malla (mesh), los AP usan un backhaul inalámbrico para llegar a un AP raíz o portal conectado a la red cableada. Las demás son funciones de radio, no diseños de backhaul.", [null, "El band steering empuja a los clientes de doble banda hacia 5 GHz; no proporciona backhaul inalámbrico entre AP.", "El channel bonding combina canales adyacentes para obtener más throughput; no enlaza AP de forma inalámbrica a un uplink cableado.", "El balanceo de carga reparte los clientes entre los AP; no transporta el tráfico de AP sin cable hacia uno cableado."]],
  "cw49": ["En una captura, ¿qué indicador del frame control muestra que una trama es una retransmisión?", ["More Data", "Retry", "Power Management", "Protected Frame"], "El bit Retry se activa cuando una trama se envía de nuevo. More Data le indica a un cliente en modo doze que hay más tramas en buffer.", ["More Data le indica a un cliente en modo doze que el AP tiene más tramas en buffer para él; no marca retransmisiones.", null, "El bit Power Management le indica al AP si la estación va a entrar en modo doze, no si la trama es un reintento.", "El bit Protected Frame muestra que el cuerpo de la trama está cifrado, no que se reenvió."]],
  "cw50": ["Los radios 802.11n y posteriores envían varias MPDU en una A-MPDU. ¿Cómo las confirma el receptor de forma eficiente?", ["Un bit en el siguiente beacon", "Un ACK separado para cada MPDU", "Una trama CTS-to-self", "Una sola trama Block Ack"], "Block Ack confirma muchas tramas a la vez con un bitmap, lo que mantiene eficiente la agregación. CTS-to-self es un mecanismo de protección.", ["Los beacons no confirman tramas de datos; anuncian el BSS y el tráfico en buffer.", "Enviar un ACK separado por cada MPDU desperdiciaría el tiempo de aire que la agregación busca ahorrar.", "CTS-to-self es un mecanismo de protección que reserva el medio antes de transmitir; no confirma las tramas recibidas.", null]],
  "cw51": ["Un auditorio debe atender a 800 usuarios. ¿Qué enfoque se ajusta MEJOR a un diseño basado en capacidad?", ["Más AP a menor potencia en canales de 20 MHz", "Menos AP a potencia máxima para cobertura total", "Canales de 80 MHz en cada AP en 2.4 GHz", "Una omnidireccional de alta ganancia en el centro de la sala"], "El diseño por capacidad crea celdas más pequeñas para que cada AP atienda a menos clientes y los canales se puedan reutilizar. La potencia máxima y los canales anchos reducen la reutilización.", [null, "Menos AP a potencia máxima crean celdas grandes con muchos clientes por AP, lo que sirve para cobertura, no para 800 usuarios.", "Los canales de 80 MHz no caben en la banda de 83.5 MHz de 2.4 GHz y, de todos modos, los canales anchos reducen la reutilización en una sala densa.", "Una sola omnidireccional pone a todos los usuarios en un AP y un canal, lo que no puede dar el tiempo de aire que necesitan 800 usuarios."]],
  "cw52": ["Un hospital está diseñando para teléfonos Wi-Fi. ¿Qué objetivo es una recomendación común de los fabricantes?", ["Unos −30 dBm sin objetivo de SNR", "Unos −85 dBm con una SNR cercana a 5 dB", "Unos −67 dBm con una SNR cercana a 25 dB", "Unos −90 dBm con una SNR cercana a 10 dB"], "Muchos fabricantes de clientes de voz recomiendan alrededor de −67 dBm y 25 dB de SNR para que sean posibles tasas más altas y pocos reintentos. −85 dBm está cerca del límite de señal utilizable.", ["-30 dBm es una señal extremadamente fuerte que solo se encuentra justo al lado de un AP, e ignorar la SNR ignora las fallas relacionadas con el ruido.", "-85 dBm con 5 dB de SNR está cerca del límite de sensibilidad de recepción y daría tasas bajas, reintentos y llamadas caídas.", null, "-90 dBm está cerca del piso de ruido y una SNR de 10 dB solo soporta las tasas más bajas, demasiado pobre para voz."]],
  "cw53": ["¿Por qué los diseños para voz exigen que cada área escuche un segundo AP con un nivel de señal utilizable?", ["Para que el controlador pueda balancear la carga por SSID", "Para que cada teléfono pueda unirse a dos AP a la vez", "Para que los teléfonos puedan hacer roaming sin cortar llamadas", "Para que la detección de radares se comparta entre los AP"], "La cobertura secundaria le da al teléfono un destino de roaming antes de que la señal actual se debilite demasiado, lo que evita huecos y llamadas caídas.", ["El balanceo de carga no está ligado a los SSID, y la cobertura secundaria existe para dar a los teléfonos un destino de roaming, no para repartir SSID.", "Una estación 802.11 se asocia con un solo AP a la vez; la cobertura secundaria no le permite unirse a dos.", null, "La detección de radares es una función DFS que cada radio realiza por sí mismo; no es la razón de la cobertura de voz superpuesta."]],
  "cw54": ["¿Qué arquitectura mantiene la configuración y el monitoreo en un servicio alojado por el fabricante, mientras los AP reenvían el tráfico de usuarios localmente?", ["Administrada desde la nube", "Autónoma", "Controlador centralizado", "Mesh independiente"], "Las WLAN administradas desde la nube alojan el plano de gestión en la nube; los datos se quedan locales. Los AP autónomos no tienen ninguna gestión central.", [null, "Los AP autónomos no tienen un servicio de gestión central; cada uno se configura por separado.", "Un controlador centralizado aloja la gestión en las instalaciones y a menudo tuneliza el tráfico de usuarios hacia sí mismo, en lugar de un servicio alojado por el fabricante.", "Un mesh independiente describe el backhaul inalámbrico entre AP, no dónde se aloja la gestión."]],
  "cw55": ["Los AP de una sucursal tunelizan todo el tráfico de usuarios a través de la WAN hacia un controlador en la oficina central, y los usuarios de la sucursal se quejan de un acceso lento a una impresora local. ¿Cuál es el MEJOR cambio?", ["Pasar los AP de la sucursal a canales de 40 MHz", "Aumentar la potencia de los AP en la sucursal", "Agregar otro SSID para acceder a la impresora", "Reenviar el tráfico de la sucursal localmente en el AP"], "El reenvío local (distribuido) mantiene el tráfico de la sucursal en la LAN de la sucursal en lugar de hacerlo ir y volver a través de la WAN. Los cambios de radio no corrigen la ruta del tráfico.", ["Los canales más anchos cambian la capacidad de radio, pero no la ruta del tráfico; las tramas seguirían yendo y volviendo por la oficina central.", "Una mayor potencia del AP afecta la cobertura, no el viaje de ida y vuelta por la WAN causado por tunelizar el tráfico a un controlador lejano.", "Un nuevo SSID seguiría tunelizándose a la oficina central a menos que cambie su modo de reenvío, y además agrega sobrecarga de beacons.", null]],
  "cw56": ["La gestión de recursos de radio (RRM) que ajusta canales y potencia entre los AP pertenece a ¿qué plano?", ["Plano de gestión", "Plano de control", "Plano de datos", "Plano de usuario"], "El plano de control coordina la red, por ejemplo RRM y roaming. El plano de gestión maneja la configuración y el monitoreo; el plano de datos reenvía el tráfico de usuarios.", ["El plano de gestión maneja la configuración, el firmware y el monitoreo, no la coordinación en vivo como RRM.", null, "El plano de datos reenvía las tramas de usuario; no decide la configuración de canal y potencia.", "El plano de usuario es otro nombre del plano de datos, que transporta el tráfico de usuarios, no las funciones de coordinación."]],
  "cw57": ["Un AP autónomo servirá tres SSID, cada uno asignado a una VLAN distinta. ¿Cómo se debe configurar el puerto del switch para el AP?", ["Como puerto enrutado sin VLAN", "Como puerto de acceso en la VLAN de invitados", "Como puerto de acceso en la VLAN nativa", "Como trunk 802.1Q con esas VLAN"], "Llevar varias VLAN al AP requiere un trunk 802.1Q. Un puerto de acceso transporta solo una VLAN.", ["Un puerto enrutado no tiene VLAN, así que no puede entregar tres VLAN separadas al AP.", "Un puerto de acceso en la VLAN de invitados transportaría solo el tráfico de invitados y dejaría a los otros dos SSID sin sus VLAN.", "Un puerto de acceso transporta solo una VLAN sin etiquetar, así que los SSID no podrían asignarse a VLAN diferentes.", null]],
  "cw58": ["Un sitio tiene ocho SSID en cada AP y una alta utilización del canal incluso cuando hay pocos usuarios activos. ¿Cuál es la causa probable?", ["Eventos DFS en la banda de 2.4 GHz", "Sobrecarga de beacons y probes por muchos SSID", "Muy pocos spatial streams en los AP", "Cifrado WPA3 demasiado fuerte"], "Cada SSID envía beacons por separado, normalmente a una tasa básica baja, así que muchos SSID consumen tiempo de aire antes de que fluya cualquier dato. DFS aplica solo a 5 GHz.", ["DFS aplica solo a ciertos canales de 5 GHz; no hay DFS en 2.4 GHz.", null, "Menos spatial streams limitan el throughput máximo, pero no crean una alta utilización cuando hay pocos usuarios activos.", "La fuerza del cifrado no agrega tiempo de aire; las tramas WPA3 son de un tamaño similar a las de WPA2."]],
  "cw59": ["Un administrador deshabilita las tasas de 1, 2, 5.5 y 11 Mbps en 2.4 GHz. ¿Cuál es el principal beneficio?", ["Cada celda de AP se vuelve más grande", "Los clientes legacy 802.11b se conectan con más facilidad", "Las tramas usan menos tiempo de aire, lo que ayuda al roaming", "Los beacons dejan de transmitirse"], "Las tasas mínimas más altas acortan las tramas de gestión y hacen las celdas efectivamente más pequeñas, lo que incentiva a los clientes a hacer roaming. Esto deja fuera a los clientes 802.11b en lugar de ayudarlos.", ["Subir la tasa de datos mínima hace las celdas efectivamente más pequeñas, no más grandes.", "Deshabilitar 1-11 Mbps impide por completo la conexión de los clientes que solo soportan 802.11b.", null, "Los beacons se siguen enviando, solo que a una tasa básica más alta, así que usan menos tiempo de aire."]],
  "cw60": ["¿Qué función incentiva a los clientes de doble banda a conectarse en 5 GHz en lugar de 2.4 GHz?", ["Band steering", "Balanceo de carga", "BSS coloring", "Dynamic Frequency Selection"], "El band steering retrasa o ignora las probe responses de 2.4 GHz para los clientes de doble banda, de modo que se unan en 5 GHz. El balanceo de carga reparte los clientes entre los AP.", [null, "El balanceo de carga reparte los clientes entre los AP según la carga; no empuja específicamente a los clientes a la banda de 5 GHz.", "BSS coloring mejora la reutilización espacial entre BSS 802.11ax superpuestos; no dirige a los clientes entre bandas.", "DFS es un requisito para evitar radares en algunos canales de 5 GHz; no mueve clientes desde 2.4 GHz."]],
  "cw61": ["Un almacén usa escáneres 1x1 que solo soportan 2.4 GHz. ¿Por qué debe detectarse esto antes de terminar el diseño?", ["Los escáneres solo pueden usar canales DFS en 5 GHz", "El diseño debe adaptarse al cliente crítico más débil", "Los clientes de 2.4 GHz necesitan canales de 160 MHz", "Solo afecta la elección del nombre del SSID"], "Las decisiones de cobertura, banda y tasas deben funcionar para los dispositivos menos capaces de los que depende el negocio, así que un diseño solo de 5 GHz fallaría con estos escáneres.", ["Los escáneres limitados a 2.4 GHz no pueden usar canales de 5 GHz en absoluto, sean DFS o no.", null, "Los canales de 160 MHz no existen en 2.4 GHz, y los escáneres 1x1 ciertamente no los necesitan.", "La banda que soporta el cliente determina la ubicación de los AP, la banda y las tasas, no solo el nombre del SSID."]],
  "cw62": ["Un switch tiene un presupuesto PoE de 370 W. El plan agrega 16 AP que pueden consumir 25.5 W cada uno. ¿Cuál es la preocupación?", ["El presupuesto PoE aplica solo a teléfonos", "Los AP necesitan 802.3af en su lugar", "El presupuesto alcanza para 32 de estos AP", "La demanda de 408 W supera el presupuesto"], "16 × 25.5 W = 408 W, por encima del presupuesto de 370 W, así que algunos AP podrían no encender o funcionar en un modo reducido.", ["Los presupuestos PoE cubren todos los dispositivos alimentados del switch, incluidos los AP, no solo los teléfonos.", "802.3af entrega solo 12.95 W en el dispositivo, muy por debajo de los 25.5 W que pueden consumir estos AP.", "370 W divididos entre 25.5 W alcanzan solo para unos 14 de estos AP a consumo máximo, no 32.", null]],
  "cw63": ["Varios AP cercanos de 5 GHz están todos en el mismo canal de 80 MHz y los usuarios ven un throughput lento. ¿Qué cambio de diseño ayuda MÁS?", ["Usar canales más estrechos para permitir más reutilización", "Aumentar la potencia de transmisión en cada AP", "Agregar más SSID para dividir a los usuarios", "Mover todos los AP al canal 36 a 160 MHz"], "Los canales más estrechos dan más canales sin superposición, lo que reduce la contención cocanal. Más potencia o canales más anchos aumentan la contención.", [null, "Aumentar la potencia hace que los AP se escuchen aún más entre sí, lo que aumenta la contención cocanal en lugar de reducirla.", "Los SSID adicionales comparten el mismo canal y agregan sobrecarga de beacons, así que reducen el tiempo de aire en lugar de dividir la carga.", "Poner todos los AP en un canal de 160 MHz no deja ninguna reutilización y empeora la contención."]],
  "cw64": ["Una pequeña empresa teme que alguien capture su handshake de Wi-Fi y adivine la contraseña offline. ¿Qué cambio ayuda MÁS?", ["Habilitar el filtrado por dirección MAC", "Ocultar el SSID de las tramas beacon", "Pasar a WPA3-Personal usando SAE", "Cambiar de CCMP a TKIP"], "SAE resiste los ataques de diccionario offline contra un intercambio capturado. Ocultar el SSID y el filtrado MAC se evaden fácilmente, y TKIP está obsoleto.", ["El filtrado MAC no protege el handshake, y las direcciones MAC se envían en claro y son fáciles de suplantar.", "Un SSID oculto sigue apareciendo en las tramas de probe y asociación y no hace nada para impedir que se adivine la passphrase offline.", null, "TKIP está obsoleto y es más débil que CCMP, y sigue usando el mismo handshake PSK que puede atacarse offline."]],
  "cw65": ["Una cafetería quiere una red abierta sin contraseña, pero con tráfico cifrado para cada cliente. ¿Qué opción es adecuada?", ["WEP con una clave compartida", "WPA2-Personal con una clave publicada", "Enhanced Open (OWE)", "Un SSID oculto"], "OWE le da a cada cliente un cifrado único sin passphrase. Una clave compartida y publicada permite que cualquiera que la tenga ataque las sesiones de otros.", ["WEP está roto y requiere una clave compartida, así que no es ni sin contraseña ni realmente seguro.", "Una clave WPA2 publicada permite que cualquiera que la conozca derive las claves de sesión de otros clientes a partir de handshakes capturados, y no es sin contraseña.", null, "Ocultar el SSID no proporciona ningún cifrado y el nombre igual se filtra en las tramas probe."]],
  "cw66": ["En una red WPA2-Enterprise, ¿qué rol de 802.1X cumple el access point o el controlador?", ["Autenticador", "Suplicante", "Servidor de autenticación", "Autoridad certificadora"], "El cliente es el suplicante, el AP o el controlador es el autenticador y RADIUS es el servidor de autenticación.", [null, "El suplicante es el dispositivo cliente que solicita acceso, no el AP ni el controlador.", "El servidor de autenticación suele ser RADIUS, que verifica las credenciales detrás del AP.", "Una autoridad certificadora emite certificados; no es uno de los tres roles de 802.1X en la WLAN."]],
  "cw67": ["Una empresa quiere autenticación mutua por certificados sin enviar contraseñas de usuario por Wi-Fi. ¿Qué método EAP es adecuado?", ["LEAP", "PEAP-MSCHAPv2", "EAP-TTLS con PAP", "EAP-TLS"], "EAP-TLS requiere certificados tanto en el servidor como en el cliente. PEAP y TTLS normalmente usan contraseñas dentro de un túnel; LEAP está obsoleto.", ["LEAP es un método obsoleto de Cisco que usa contraseñas (MS-CHAP) y es vulnerable a ataques de diccionario.", "PEAP-MSCHAPv2 usa solo un certificado de servidor y autentica al usuario con una contraseña dentro del túnel.", "EAP-TTLS con PAP envía una contraseña de usuario dentro de un túnel TLS y no requiere certificados de cliente.", null]],
  "cw68": ["¿Qué protocolo de cifrado es obligatorio para WPA2?", ["TKIP, basado en RC4", "CCMP, basado en AES", "WEP con claves de 104 bits", "Triple DES en modo CBC"], "La certificación WPA2 exige CCMP (AES). TKIP fue una solución provisional para el hardware WEP y ahora está obsoleto.", ["TKIP fue la solución provisional de WPA basada en RC4 para hardware antiguo; es opcional en WPA2 y ahora está obsoleto.", null, "WEP es anterior a WPA2, está roto y no se permite en WPA2 en absoluto.", "Triple DES no lo usa ninguna suite de seguridad 802.11; WPA2 se basa en AES."]],
  "cw69": ["Los clientes se siguen desconectando de un SSID, y una captura muestra ráfagas de tramas de desautenticación que suplantan la dirección MAC del AP. ¿Qué función previene este ataque?", ["Band steering", "Fast BSS transition (802.11r)", "Neighbor reports (802.11k)", "Protected Management Frames (802.11w)"], "802.11w protege las tramas de desautenticación y desasociación para que las falsificadas se ignoren. 802.11r solo acelera el roaming.", ["El band steering mueve a los clientes de doble banda a 5 GHz y no da protección contra tramas de gestión falsificadas.", "802.11r acelera el roaming con claves derivadas por adelantado, pero no autentica las tramas de desautenticación.", "Los neighbor reports de 802.11k ayudan a los clientes a elegir destinos de roaming y no hacen nada contra la desautenticación suplantada.", null]],
  "cw70": ["El WIPS encuentra un AP no administrado conectado a una toma de red de una sala de conferencias en la LAN corporativa. ¿Cómo se clasifica?", ["AP vecino", "AP rogue", "Mesh portal", "AP administrado"], "Un AP rogue no está autorizado y está conectado a la red cableada de la organización. Un AP vecino pertenece a otra persona y no está en tu LAN.", ["Un AP vecino pertenece a otra persona y no está conectado a tu LAN cableada, a diferencia de este.", null, "Un mesh portal es un AP autorizado que conecta el tráfico de la malla con la red cableada, no un dispositivo no administrado.", "Un AP administrado está autorizado y controlado por tu sistema WLAN, cosa que este AP no administrado no es."]],
  "cw71": ["En WPA2-Personal, ¿de dónde proviene la Pairwise Master Key?", ["De la group temporal key", "De la respuesta del servidor RADIUS", "De la passphrase y el SSID", "Solo del BSSID del AP"], "Con una PSK, la PMK se deriva de la passphrase y el SSID. En modo Enterprise proviene del intercambio EAP con RADIUS.", ["La GTK se entrega durante el 4-way handshake y se deriva por separado; no es el origen de la PMK.", "RADIUS proporciona el origen de la PMK solo en modo Enterprise; WPA2-Personal no usa servidor RADIUS.", null, "El BSSID (dirección MAC del AP) se usa para derivar la PTK, pero la PMK proviene de la passphrase y el SSID."]],
  "cw72": ["Un SSID de invitados debe impedir que los dispositivos de los invitados se comuniquen entre sí. ¿Qué configuración se debe usar?", ["Aislamiento de clientes", "Filtrado MAC", "Ocultar el SSID", "Un intervalo DTIM más largo"], "El aislamiento de clientes (peer-to-peer) bloquea el tráfico entre clientes inalámbricos. El filtrado MAC y ocultar el SSID no detienen el tráfico entre clientes.", [null, "El filtrado MAC solo controla qué dispositivos pueden asociarse; no impide que los invitados asociados se comuniquen entre sí.", "Ocultar el SSID solo quita el nombre de los beacons y no tiene efecto en el tráfico entre clientes.", "El intervalo DTIM controla la entrega de tramas de grupo en buffer a los clientes en modo doze, no el tráfico entre clientes."]],
  "cw73": ["Un ingeniero recorre un sitio registrando la señal y el ruido de cada AP sin asociarse a ninguno. ¿Qué tipo de site survey es este?", ["Survey activo", "Survey pasivo", "Survey predictivo", "Survey solo de espectro"], "Un survey pasivo escucha a todos los AP. Un survey activo se asocia y mide throughput, reintentos y roaming.", ["Un survey activo se asocia a la red para medir throughput, reintentos y roaming, cosa que este ingeniero no está haciendo.", null, "Un survey predictivo se hace en software a partir de planos, sin recorrer el sitio con un adaptador en vivo.", "Un survey solo de espectro registra la energía de RF en bruto, no la señal y el ruido por AP a partir de tramas Wi-Fi decodificadas."]],
  "cw74": ["Antes de que un edificio nuevo esté terminado, un diseñador usa planos y valores de atenuación de muros en un software para planificar las ubicaciones de los AP. ¿Qué tipo de survey es este?", ["Survey de validación", "Survey pasivo", "Survey activo", "Survey predictivo"], "Un survey predictivo modela la RF con software y datos del edificio antes de instalar los AP. Los demás necesitan mediciones en el sitio.", ["Un survey de validación mide una red en funcionamiento después de la instalación; aquí el edificio ni siquiera está terminado.", "Un survey pasivo requiere recorrer el sitio y escuchar AP reales, lo cual es imposible antes de la instalación.", "Un survey activo requiere asociarse a una red en funcionamiento en el sitio, que todavía no existe.", null]],
  "cw75": ["Los usuarios de una sala de descanso pierden el Wi-Fi de 2.4 GHz alrededor de la hora del almuerzo, pero 5 GHz funciona bien. ¿Qué herramienta identifica MEJOR la fuente?", ["Analizador de espectro", "Analizador de protocolos", "Probador de cables", "Log de depuración de RADIUS"], "La causa probable es energía no Wi-Fi, como un horno de microondas, que solo muestra un analizador de espectro. Un analizador de protocolos solo decodifica tramas 802.11.", [null, "Un analizador de protocolos solo decodifica tramas 802.11, así que puede mostrar reintentos, pero no una fuente no Wi-Fi como un horno de microondas.", "Un probador de cables verifica el cableado Ethernet y no puede detectar interferencia de RF.", "Los logs de depuración de RADIUS muestran resultados de autenticación, que no explicarían una caída solo en 2.4 GHz a la hora del almuerzo."]],
  "cw76": ["Una laptop con Wireshark muestra solo su propio tráfico y ningún beacon de otras redes. ¿Qué debe cambiar para ver todas las tramas 802.11 de un canal?", ["Unirse a cada SSID que se quiera capturar", "Activar el modo promiscuo en el puerto del switch", "Poner el adaptador en modo monitor en ese canal", "Usar un puerto espejo cableado en el uplink del AP"], "El modo monitor permite que un adaptador inalámbrico capture todas las tramas 802.11 de su canal, incluidas las de gestión y control. El espejo cableado nunca muestra tramas de RF.", ["Unirse a los SSID no permite que el adaptador vea las tramas de otras estaciones; sigue capturando solo su propio tráfico.", "El modo promiscuo en un puerto de switch es un concepto cableado y no afecta lo que escucha un adaptador inalámbrico.", null, "Un puerto espejo cableado muestra las tramas Ethernet después de que el AP las convierte, nunca beacons ni otras tramas de RF 802.11."]],
  "cw77": ["Dos laptops en extremos opuestos de una sala larga se conectan al AP central, pero no pueden escucharse entre sí, y los reintentos son altos. ¿Cuál es el problema probable?", ["Contención cocanal", "Interferencia de canal adyacente", "Nodo oculto", "Cliente pegajoso (sticky client)"], "Las estaciones que no pueden escucharse transmiten al mismo tiempo y colisionan en el AP. RTS/CTS, la ubicación del AP o celdas más pequeñas pueden ayudar.", ["La contención cocanal involucra dispositivos que se escuchan entre sí y comparten el tiempo de aire; estas laptops no pueden escucharse.", "La interferencia de canal adyacente proviene de canales vecinos superpuestos; aquí ambas laptops usan el mismo AP y canal.", null, "Un sticky client se queda en un AP lejano en lugar de hacer roaming; estas laptops están ambas conectadas correctamente al AP central."]],
  "cw78": ["Doce AP en una oficina abierta están todos en el canal 6 a máxima potencia, y el tiempo de aire está saturado. ¿Cuál es la MEJOR solución?", ["Reducir la potencia y repartir los AP entre canales", "Subir la potencia de todos los AP para superar el ruido", "Habilitar canales de 40 MHz en 2.4 GHz", "Agregar un segundo SSID en el canal 6"], "Los AP se escuchan entre sí y deben compartir el tiempo de aire (contención cocanal). Menor potencia y más canales, idealmente en 5 GHz, restauran la capacidad.", [null, "Subir la potencia hace que los AP se escuchen desde más lejos, lo que aumenta la contención cocanal en lugar de corregirla.", "40 MHz en 2.4 GHz deja solo un canal limpio, lo que empeoraría la contención.", "Un segundo SSID en el mismo canal agrega sobrecarga de beacons y comparte el mismo tiempo de aire saturado."]],
  "cw79": ["Un cliente se mantiene conectado a un AP lejano con señal débil incluso cuando está parado debajo de otro AP. ¿Cómo se llama esto?", ["Un evil twin", "Un nodo oculto", "Un cliente rogue", "Un sticky client"], "Los sticky clients retrasan el roaming. 802.11k/v, subir las tasas básicas mínimas y ajustar la potencia pueden incentivarlos a moverse.", ["Un evil twin es un AP malicioso que imita un SSID legítimo; esto es un cliente normal que no hace roaming.", "Un nodo oculto es una estación que otras estaciones no pueden escuchar, lo que causa colisiones, no una que se niega a hacer roaming.", "Un cliente rogue es un dispositivo no autorizado; este cliente está autorizado pero tarda en hacer roaming.", null]],
  "cw80": ["Un teléfono muestra todas las barras de señal, pero las subidas son muy lentas, y el AP está configurado a su potencia máxima. ¿Cuál es una causa probable?", ["El teléfono usa un valor DTIM demasiado alto", "La potencia del AP supera con creces la del teléfono", "La banda de 2.4 GHz del AP está apagada", "El SSID se envía en cada beacon"], "El teléfono escucha bien al AP potente, pero sus transmisiones más débiles llegan mal al AP, lo que causa reintentos en el uplink. Ajustar la potencia del AP a la capacidad del cliente ayuda.", ["DTIM afecta la frecuencia con que un cliente en modo doze se despierta para el tráfico de grupo, no el throughput de subida.", null, "Apagar 2.4 GHz no haría que las subidas de un teléfono conectado fueran lentas mientras muestra todas las barras.", "Enviar el SSID en los beacons es un comportamiento normal y no tiene efecto en el uplink del teléfono."]],
  "cw81": ["Una captura hecha junto al AP se ve limpia, pero el usuario que está lejos sigue quejándose. ¿Dónde se debe hacer la siguiente captura?", ["Junto a otro AP", "En el switch de core", "En el servidor RADIUS", "Cerca del cliente afectado"], "Captura cerca del cliente, en su canal, para ver lo que escucha y lo que envía. Las capturas cableadas no ven el comportamiento de RF en absoluto.", ["La ubicación de otro AP muestra lo que escucha ese AP, no lo que experimenta el cliente afectado.", "Una captura en el switch de core muestra solo tramas cableadas y no ve problemas de RF como reintentos o interferencia cerca del cliente.", "El servidor RADIUS muestra resultados de autenticación, no las condiciones de RF que experimenta el cliente.", null]],
  "cw82": ["¿Qué estadística de captura apunta MÁS directamente a problemas de RF como interferencia o colisiones?", ["Una cantidad alta de beacons", "Una tasa alta de reintentos", "Un intervalo DTIM largo", "Muchas probe responses"], "Las retransmisiones significan que las tramas no fueron confirmadas, a menudo por interferencia, colisiones o señal débil. La cantidad de beacons es tráfico normal de fondo.", ["Los beacons son tráfico de gestión normal de fondo, así que una cantidad alta no indica interferencia ni colisiones.", null, "El intervalo DTIM es un parámetro de configuración para la entrega de tráfico de grupo, no un síntoma de problemas de RF.", "Muchas probe responses suelen reflejar clientes escaneando o muchos SSID, no pérdida de tramas por interferencia."]],
  "cw83": ["Después de instalar los AP, el cliente quiere pruebas de que se cumplieron los objetivos del diseño. ¿Qué actividad las proporciona?", ["Una certificación del cableado", "Una actualización del diseño predictivo", "Un survey de validación posterior a la instalación", "Una nueva entrevista de requisitos"], "Un survey de validación mide la red en funcionamiento contra los requisitos acordados. Los modelos predictivos son estimaciones, no pruebas.", ["La certificación del cableado demuestra que los tendidos cumplen su categoría, no que se cumplan los objetivos de diseño de RF.", "Una actualización predictiva sigue siendo un modelo de software y no puede demostrar lo que realmente entrega la red instalada.", null, "Una entrevista de requisitos recopila objetivos antes del diseño; no mide si se lograron."]],
  "cw84": ["Todos los clientes WPA2-Enterprise empezaron a fallar en la autenticación la misma mañana sin cambios de configuración. Los logs de PEAP muestran un error de certificado del servidor. ¿Cuál es la causa probable?", ["El certificado del servidor RADIUS expiró", "La PSK se cambió durante la noche", "El AP se movió a un canal DFS", "El scope de DHCP se quedó sin leases"], "Un certificado de servidor expirado rompe PEAP y EAP-TLS para todos los clientes a la vez. No hay PSK en modo Enterprise, y DHCP ocurre después de la autenticación.", [null, "WPA2-Enterprise usa 802.1X/EAP y no tiene PSK, así que cambiar una no podría causar esto.", "Un cambio a un canal DFS causa una desconexión breve, no errores de certificado de servidor PEAP para todos los clientes.", "DHCP ocurre después de una autenticación exitosa, así que un scope agotado no causaría errores de certificado en PEAP."]],
  "cw85": ["En una red WPA2-Personal, una captura muestra los mensajes EAPOL 1 y 2, pero el AP nunca envía el mensaje 3. ¿Qué es lo MÁS probable que esté mal?", ["Expiró el certificado RADIUS del cliente", "El cliente tiene la passphrase incorrecta", "Al AP le falta una reserva DHCP", "El AP usa un SSID oculto"], "El AP verifica el MIC en el mensaje 2; con una passphrase que no coincide, la verificación falla y el AP no continúa. El modo Personal no usa RADIUS.", ["WPA2-Personal usa una clave precompartida, no RADIUS, así que no hay ningún certificado RADIUS involucrado.", null, "DHCP se ejecuta solo después de que el 4-way handshake tiene éxito, así que no puede impedir que se envíe el mensaje 3.", "Un SSID oculto solo afecta el descubrimiento; el cliente ya se asoció y comenzó el handshake."]],
  "cw86": ["Dos AP vecinos de 2.4 GHz están en los canales 1 y 3. ¿Qué problema crea esto?", ["Eventos de radar DFS", "Solo contención cocanal", "Colisiones por nodo oculto", "Interferencia de canal adyacente"], "Los canales distintos pero superpuestos no pueden compartir el medio correctamente y corrompen las tramas del otro. Usa 1, 6 y 11 en su lugar.", ["DFS aplica a ciertos canales de 5 GHz, no a los canales 1 y 3 de 2.4 GHz.", "La contención cocanal ocurre cuando los AP comparten el mismo canal; los canales 1 y 3 son distintos pero se superponen.", "Un nodo oculto es una estación que los demás no pueden escuchar; este problema proviene de asignaciones de canal superpuestas.", null]],
  "cw87": ["Durante un survey activo, el ingeniero coloca un AP temporal en un soporte en las ubicaciones planificadas para encontrar el borde de la celda. ¿Cómo se llama este método?", ["Survey AP-on-a-stick", "Modelado predictivo", "Recorrido pasivo", "Barrido de espectro"], "AP-on-a-stick usa un AP temporal para medir la cobertura real en los puntos candidatos antes del montaje final.", [null, "El modelado predictivo se hace en software a partir de planos, sin colocar un AP real en el sitio.", "Un recorrido pasivo escucha los AP ya instalados en lugar de colocar un AP temporal en los puntos candidatos.", "Un barrido de espectro mide la energía de RF y la interferencia, no el borde de la celda de cobertura de un AP temporal."]],
  "cw88": ["Un analizador de espectro muestra una fuente con un ciclo de trabajo cercano al 100% en los canales 1 a 4. ¿Qué les pasa a los dispositivos Wi-Fi allí?", ["Suben la potencia hasta que el ruido se detiene", "Se cambian a 6 GHz por su cuenta", "Difieren constantemente y no pueden transmitir", "Lo ignoran porque no es 802.11"], "Una señal constante no Wi-Fi mantiene ocupado el CCA o arruina la SNR, así que los dispositivos difieren o no logran decodificar. Elimina la fuente o cambia de canal.", ["Los dispositivos Wi-Fi no pueden superar a un interferente constante, y subir la potencia no elimina la energía que produce otro dispositivo.", "Los clientes no cambian de banda por su cuenta a causa de la interferencia; además, 6 GHz requiere hardware compatible con 6 GHz.", null, "La detección de energía del CCA reacciona a cualquier energía fuerte, no solo a tramas 802.11, así que las señales no Wi-Fi siguen bloqueando las transmisiones."]],
  "cw89": ["Una laptop se asocia al SSID corporativo y completa el handshake, pero obtiene una dirección 169.254.x.x. ¿En qué debe enfocarse ahora la resolución de problemas?", ["En las tramas de autenticación 802.11", "En la polarización de la antena", "En DHCP y la asignación de VLAN del SSID", "En el canal y la potencia del AP"], "El enlace Wi-Fi funciona; el problema es el direccionamiento de capa 3, a menudo una VLAN incorrecta en el SSID o en el trunk, o un problema con el scope o el relay de DHCP.", ["La autenticación 802.11 y el 4-way handshake ya tuvieron éxito, así que la capa de enlace funciona.", "La polarización afecta la intensidad de la señal, pero la laptop ya tiene un enlace Wi-Fi funcionando.", null, "El canal y la potencia son parámetros de RF; la laptop está conectada y la falla está en el direccionamiento IP."]],
  "cw90": ["¿Qué hallazgo de utilización del canal sugiere MÁS que una celda no puede aceptar más clientes?", ["La utilización se mantiene alta en horas pico", "La utilización es baja todo el día", "La utilización sube por un momento", "La utilización es la misma en cada banda"], "Una utilización constantemente alta en los períodos pico significa que queda poco tiempo de aire para clientes nuevos. Los picos breves son normales.", [null, "Una utilización baja todo el día significa que hay mucho tiempo de aire libre, así que la celda puede aceptar más clientes.", "Los picos breves son normales cuando el tráfico llega en ráfagas y no demuestran que la celda se quedó sin capacidad.", "Una utilización igual en cada banda no dice nada sobre si esa utilización es alta o baja."]],
  "x1": ["Dos copias de la misma señal llegan a un receptor con igual amplitud, pero desfasadas 180 grados. ¿Cuál es el resultado?", ["La señal recibida casi duplica su intensidad (upfade)", "La tasa de datos aumenta porque las copias se combinan", "Las copias se cancelan entre sí y dejan un nulo profundo", "La señal se desplaza a una frecuencia más baja"], "Las ondas desfasadas 180 grados con igual amplitud se cancelan, así que el multipath puede producir un nulo. Un upfade ocurre solo cuando las copias llegan casi en fase, que es el caso opuesto.", ["Un upfade necesita que las copias lleguen casi en fase; a 180 grados se restan en lugar de sumarse.", "Los receptores sin combinación MIMO no ganan nada con copias que se cancelan, y la cancelación reduce la tasa utilizable.", null, "Las diferencias de fase cambian cómo se suman las ondas; no cambian la frecuencia portadora."]],
  "x2": ["La hoja de datos de un cliente indica una sensibilidad de recepción de -82 dBm para su MCS más bajo y de -64 dBm para su MCS más alto. En un escritorio escucha al AP a -70 dBm. ¿Qué puede hacer el cliente allí?", ["Decodificar el MCS más bajo, pero no el más alto", "Decodificar el MCS más alto, pero no el más bajo", "No decodificar ninguna de las tasas, así que no puede asociarse", "Decodificar ambos, ya que la sensibilidad aplica solo a los AP"], "-70 dBm es más fuerte que -82 dBm, pero más débil que -64 dBm, así que solo se soporta la tasa más baja. Leer -70 como más fuerte que -64 es el clásico error de signo con valores negativos de dBm.", [null, "-70 dBm es más débil que -64 dBm, así que la señal está por debajo de lo que necesita el MCS más alto.", "-70 dBm es más fuerte que -82 dBm, así que el MCS más bajo se puede decodificar y el cliente puede asociarse.", "La sensibilidad de recepción es una propiedad de todo receptor, incluidos los radios de los clientes, no solo de los AP."]],
  "x3": ["Un cálculo de enlace muestra que la señal recibida de un puente quedará exactamente en el valor de sensibilidad de recepción del radio. ¿Por qué este diseño es débil?", ["El EIRP tendría que estar por encima del límite legal", "La zona de Fresnel tendría que estar totalmente bloqueada", "Los valores de sensibilidad de recepción aplican solo a antenas omnidireccionales", "No hay margen de desvanecimiento (fade margin) para las variaciones normales de la señal"], "La señal varía con el clima, el multipath y la interferencia, así que los enlaces necesitan un fade margin por encima de la sensibilidad de recepción. Quedar en el nivel de sensibilidad no implica ninguna violación del EIRP; el EIRP se fija en el lado de transmisión.", ["El EIRP lo determinan la potencia del transmisor, la pérdida del cable y la ganancia de la antena; el nivel recibido no dice nada sobre si se excede.", "Un nivel recibido igual a la sensibilidad no significa que la zona de Fresnel esté bloqueada; puede estar despejada y ser simplemente un enlace demasiado largo.", "La sensibilidad de recepción es una especificación del radio y aplica sin importar qué antena esté conectada.", null]],
  "x4": ["La hoja de datos de una antena indica un ancho de haz horizontal de 60 grados. ¿Qué mide esta cifra?", ["El ángulo completo en el que la antena irradia cualquier ganancia utilizable", "El ángulo entre los puntos donde la potencia está 3 dB por debajo del pico", "El ancho físico del elemento reflector de la antena", "El ángulo en el que comienza el lóbulo trasero de la antena"], "El ancho de haz se mide entre los puntos de media potencia (-3 dB) del lóbulo principal. La energía se sigue irradiando fuera de ese ángulo, así que no es el ángulo completo de ganancia utilizable.", ["Las antenas siguen irradiando fuera del ancho de haz; la cifra marca solo los puntos de media potencia del lóbulo principal.", null, "El ancho de haz es una medición eléctrica de radiación, no una dimensión física de la antena.", "El lóbulo trasero es una parte separada del patrón; el ancho de haz describe el ancho del lóbulo principal."]],
  "x5": ["Un ingeniero está leyendo el diagrama de azimut de una antena. ¿Qué vista del patrón de radiación muestra?", ["La vista lateral del patrón vertical", "La vista desde arriba del patrón horizontal", "El VSWR medido en todas las frecuencias soportadas", "La polarización en cada ángulo de elevación"], "El diagrama de azimut es el patrón horizontal visto desde arriba. La vista lateral del patrón vertical es el diagrama de elevación, que es la confusión habitual.", ["La vista lateral del patrón vertical es el diagrama de elevación, no el de azimut.", null, "El VSWR se muestra en un gráfico separado de impedancia o pérdida de retorno, no en el patrón de radiación.", "La polarización se indica como una sola propiedad de la antena, no se grafica por ángulo en el diagrama de azimut."]],
  "x6": ["Para un enlace punto a punto de muchos kilómetros, el ingeniero agrega altura adicional a las antenas por la curvatura terrestre (earth bulge). ¿Por qué?", ["Los enlaces más largos siempre deben pasar a frecuencias más bajas para llegar más lejos", "La curvatura terrestre se suma a la pérdida de trayectoria en espacio libre", "Corrige el desajuste de polarización entre los sitios", "La curvatura de la Tierra puede invadir la zona de Fresnel"], "En distancias largas, la curvatura de la Tierra se eleva dentro de la trayectoria y puede bloquear parte de la zona de Fresnel, así que se elevan las antenas. La pérdida de trayectoria en espacio libre depende de la distancia y la frecuencia, no de la curvatura en sí.", ["La elección de frecuencia depende de las regulaciones y las necesidades; la curvatura terrestre se resuelve elevando las antenas, no cambiando de banda.", "La pérdida de trayectoria en espacio libre proviene de la distancia y la frecuencia; la curvatura agrega una obstrucción, no pérdida adicional por dispersión.", "El desajuste de polarización proviene de la orientación de las antenas y se corrige alineándolas, no con la altura.", null]],
  "x7": ["Un AP realiza transmit beamforming explícito hacia un solo cliente. ¿Qué está haciendo?", ["Ajustar la fase de cada antena para que las señales se combinen en el cliente", "Enviar un spatial stream distinto a varios clientes diferentes a la vez", "Girar físicamente una antena direccional hacia el cliente", "Subir la potencia por encima del límite legal para ese cliente"], "El transmit beamforming usa la retroalimentación del canal para ajustar la fase de cada cadena de transmisión, de modo que las señales se sumen de forma constructiva en el cliente. Atender a varios clientes a la vez con streams separados es MU-MIMO, no beamforming de un solo usuario.", [null, "Enviar streams separados a varios clientes a la vez es MU-MIMO, no beamforming de un solo usuario.", "El beamforming se hace electrónicamente ajustando la fase; nada se mueve físicamente.", "El beamforming concentra la energía, pero debe mantenerse dentro de los límites regulatorios de potencia."]],
  "x8": ["Un AP 802.11ac Wave 2 envía datos a tres smartphones de un solo stream en el mismo momento y en el mismo canal. ¿Qué función está usando?", ["Channel bonding", "MIMO de un solo usuario", "MU-MIMO de bajada", "Maximal ratio combining"], "El MU-MIMO de bajada permite que un AP envíe spatial streams separados a varios clientes simultáneamente. El MIMO de un solo usuario envía múltiples streams a un cliente, y cada uno de estos teléfonos soporta solo un stream.", ["El channel bonding ensancha el canal para una transmisión; no atiende a varios clientes a la vez.", "El MIMO de un solo usuario envía múltiples streams a un cliente, y cada uno de estos teléfonos soporta solo un stream.", null, "Maximal ratio combining es una técnica de recepción que combina copias en un radio, no un método multicliente."]],
  "x9": ["A medida que un cliente se aleja de su AP, su tasa baja de un MCS 256-QAM a un MCS 16-QAM. ¿Por qué el radio baja de nivel?", ["16-QAM usa un canal más ancho que llega más lejos", "256-QAM solo está permitido en la banda de 6 GHz", "Una modulación de menor orden necesita menos SNR para decodificarse", "El AP cambia a DSSS a los clientes lejanos"], "Las constelaciones densas como 256-QAM necesitan una SNR alta, así que cuando la señal baja el radio elige una modulación de menor orden que todavía pueda decodificar. El ancho de canal es independiente de la modulación, así que la afirmación del canal más ancho es falsa.", ["El ancho de canal y la modulación son decisiones separadas; 16-QAM no implica un canal más ancho.", "256-QAM se usa en 5 GHz desde 802.11ac, no está restringido a 6 GHz.", null, "Un cliente 802.11ac/ax no baja a DSSS; pasa a un MCS OFDM más bajo."]],
  "x10": ["Los fabricantes recomiendan colocar los AP de 6 GHz en Preferred Scanning Channels (PSC). ¿Cuál es la razón principal?", ["Los clientes pueden limitar el probing a los PSC, así que encuentran los AP más rápido", "Los PSC son los únicos canales de 6 GHz exentos de cualquier regla DFS", "Los PSC permiten más potencia que otros canales de 6 GHz", "Solo los PSC soportan WPA3 en la banda de 6 GHz"], "La banda de 6 GHz tiene muchos canales, así que los clientes pueden hacer probing solo en los PSC; los AP ubicados en PSC se descubren más rápido. WPA3 o Enhanced Open es obligatorio en toda la operación de 6 GHz, no solo en los PSC.", [null, "DFS es una regla de radares de 5 GHz; los PSC existen para acelerar el descubrimiento de clientes, no para evitar DFS.", "Los límites de potencia en 6 GHz dependen de la clase de dispositivo y de las reglas, no de si un canal es PSC.", "WPA3 o Enhanced Open es obligatorio en todos los canales de 6 GHz, no solo en los PSC."]],
  "x11": ["Un controlador quiere sugerir que un cliente en un AP congestionado se mueva a un AP mejor. ¿Qué enmienda define la solicitud de BSS Transition Management que envía?", ["802.11r", "802.11k", "802.11e", "802.11v"], "802.11v define BSS Transition Management, que permite a la red sugerir un roaming. 802.11k da neighbor reports a los clientes, pero no les pide que se muevan.", ["802.11r acelera el roaming en sí con fast BSS transition, pero no permite que la red sugiera un cambio.", "802.11k entrega neighbor reports a pedido; no incluye la solicitud de transición en sí.", "802.11e define QoS (la base de WMM), no sugerencias de roaming.", null]],
  "x12": ["Un fabricante promociona un nuevo AP como Wi-Fi 6E. ¿Qué le dice eso al comprador?", ["Que soporta la operación multienlace de 802.11be", "Que es 802.11ax extendido a la banda de 6 GHz", "Que usa tasas 802.11ac solo en 2.4 GHz", "Que está certificado para operar con 802.11ad en la banda de 60 GHz"], "Wi-Fi 6E es el nombre de la Wi-Fi Alliance para los dispositivos 802.11ax que también operan en 6 GHz. La operación multienlace pertenece a 802.11be, que es Wi-Fi 7.", ["La operación multienlace pertenece a 802.11be (Wi-Fi 7), no a Wi-Fi 6E.", null, "802.11ac es Wi-Fi 5 y opera en 5 GHz, y no tiene nada que ver con el nombre 6E.", "802.11ad es un estándar separado de 60 GHz y no es a lo que se refiere el nombre Wi-Fi 6E."]],
  "x13": ["¿Qué conjunto de funciones está asociado con 802.11be (Wi-Fi 7)?", ["TKIP y el primer uso de BSS coloring", "Canales de 320 MHz, 4096-QAM y operación multienlace", "Canales DSSS de 22 MHz solo en 2.4 GHz", "El primer MIMO y los canales de 40 MHz"], "802.11be agrega canales de 320 MHz en 6 GHz, 4096-QAM y operación multienlace. MIMO y los canales de 40 MHz llegaron por primera vez con 802.11n (HT).", ["TKIP es una función obsoleta de WPA y BSS coloring se introdujo en 802.11ax, no en 802.11be.", null, "Los canales DSSS de 22 MHz en 2.4 GHz describen 802.11b, el PHY más antiguo de esta lista.", "MIMO y los canales de 40 MHz llegaron por primera vez con 802.11n (HT), mucho antes de Wi-Fi 7."]],
  "x14": ["Un AP 802.11g/n ve que se asocia un cliente que solo soporta 802.11b. ¿Qué cambia para los clientes OFDM del BSS?", ["Deben enviar todas sus tramas de datos con tasas DSSS", "Pierden la capacidad de usar WPA2", "Deben pasarse al canal 14 de 2.4 GHz", "Empiezan a usar protección antes de las tramas OFDM"], "El AP señala la protección en su elemento ERP, así que las estaciones OFDM usan RTS/CTS o CTS-to-self que el cliente DSSS puede entender. Siguen enviando datos con OFDM; solo las tramas de protección usan una tasa legacy.", ["Las estaciones OFDM siguen enviando datos con OFDM; solo las tramas de protección usan una tasa que el cliente DSSS entiende.", "El modo de protección no tiene efecto sobre qué métodos de seguridad se pueden usar en el BSS.", "El canal 14 no es un mecanismo de protección y no está permitido para OFDM en la mayoría de las regiones.", null]],
  "x15": ["¿Qué propósito cumple Transmit Power Control (TPC) en las bandas reguladas de 5 GHz?", ["Permitir que los dispositivos bajen la potencia para reducir la interferencia con otros usuarios", "Subir automáticamente la potencia del cliente para igualar la del AP", "Detectar radares y mover el AP a un nuevo canal", "Permitir que el AP supere su límite de EIRP cuando está inactivo"], "TPC permite que los dispositivos reduzcan la potencia de transmisión para interferir menos con otros usuarios de la banda, como sistemas de radar o satelitales. Detectar radares y cambiar de canal es DFS, un requisito separado.", [null, "TPC permite que los dispositivos reduzcan la potencia cuando corresponde; no obliga a los clientes a igualar la potencia del AP.", "Detectar radares y cambiar de canal es DFS, un requisito relacionado pero separado.", "Ningún mecanismo permite que un AP supere su límite de EIRP; TPC se trata de mantenerse más bajo, no más alto."]],
  "x16": ["En 5 GHz, un canal de 40 MHz se forma agrupando los canales 36 y 40. ¿Qué número de canal se usa comúnmente para etiquetar el centro del canal agrupado?", ["36", "40", "38", "44"], "Los números de canal están separados 5 MHz, así que el centro de 36 y 40 agrupados es el canal 38. El canal 36 es solo el canal primario o el de 20 MHz inferior, no el centro.", ["El canal 36 es el canal de 20 MHz inferior del par, no el centro del canal de 40 MHz.", "El canal 40 es el canal de 20 MHz superior del par, no el centro.", null, "El canal 44 está fuera del par 36 y 40 y pertenece al siguiente canal de 40 MHz."]],
  "x17": ["En 802.11ax, ¿cómo coordina un AP una transmisión OFDMA de subida de varios clientes?", ["Cada cliente elige una resource unit al azar tras esperar un DIFS", "Los clientes envían tramas RTS con sus resource units", "El AP envía una trigger frame que asigna las resource units", "El AP le da a cada cliente un espacio fijo en el beacon"], "El OFDMA de subida lo programa el AP con una trigger frame que le indica a cada cliente qué resource unit usar y cuándo. Los clientes no eligen las unidades por sí mismos tras la contención normal.", ["El OFDMA de subida lo programa el AP; los clientes no eligen resource units por su cuenta tras la contención normal.", "Las tramas RTS no llevan asignaciones de resource units; el AP decide la asignación.", null, "Los beacons no asignan resource units de OFDMA; eso lo hacen las trigger frames en cada transmisión."]],
  "x18": ["Un modelo de AP se vende en varios países. ¿Por qué los instaladores deben configurar el código de país correcto?", ["Define los canales y la potencia permitidos según las reglas locales", "Elige qué programa de certificación de la Wi-Fi Alliance le aplica", "Cambia qué enmienda del IEEE ejecuta el AP", "Define el idioma usado en el nombre del SSID"], "El código de país carga el dominio regulatorio: canales legales, límites de potencia y reglas DFS. La certificación de la Wi-Fi Alliance es una propiedad del producto, no algo que seleccione la configuración de país.", [null, "La certificación de la Wi-Fi Alliance la obtiene el producto durante las pruebas; no se elige con una configuración de país.", "Las enmiendas del IEEE soportadas las fija el hardware; el código de país solo aplica las reglas locales.", "Los nombres de SSID son texto libre elegido por el administrador y no tienen relación con el código de país regulatorio."]],
  "x19": ["Dos AP 802.11ax en el mismo canal usan BSS colors diferentes. ¿Cómo puede esto ayudar a una estación de uno de los BSS?", ["Cifra las tramas enviadas por el otro BSS", "Mueve automáticamente el otro BSS a un canal diferente sin superposición", "Permite que las estaciones dejen de escuchar los beacons", "Puede aplicar un umbral CCA más alto a las tramas del otro BSS"], "BSS coloring soporta la reutilización espacial: una estación puede tratar las tramas débiles con otro color usando un umbral menos sensible y transmitir de todos modos. No cambia de canal; los AP siguen compartiendo el canal.", ["El BSS color es un pequeño identificador, no un mecanismo de cifrado; la seguridad sigue viniendo de WPA2 o WPA3.", "El coloring no cambia de canal; ambos BSS se quedan en el canal compartido y usan reutilización espacial en su lugar.", "Las estaciones siguen dependiendo de los beacons para la sincronización y los parámetros; el coloring no elimina esa necesidad.", null]],
  "x20": ["¿Por qué los canales 1 y 2 de 2.4 GHz interfieren entre sí?", ["El canal 2 está reservado para uso de radares", "Los centros están separados 5 MHz, pero cada señal tiene unos 20 MHz de ancho", "Ambos canales están limitados solo a DSSS", "Usan polarización de antena opuesta"], "Los centros de los canales de 2.4 GHz están separados solo 5 MHz, mientras que cada transmisión tiene aproximadamente 20 a 22 MHz de ancho, así que los canales vecinos se superponen. Las reglas de radar y DFS aplican en partes de 5 GHz, no al canal 2.", ["Las reglas de radar y DFS aplican a partes de 5 GHz, no al canal 2 de 2.4 GHz.", null, "OFDM (802.11g/n) también funciona en estos canales, y compartir un tipo de PHY no es lo que causa la superposición.", "Los canales no tienen una polarización fija; esa es una propiedad de las antenas."]],
  "x21": ["Un AP debe soportar clientes 802.11a antiguos. ¿Qué banda y qué familia de PHY usa 802.11a?", ["2.4 GHz con DSSS", "5 GHz con OFDM", "2.4 GHz con ERP-OFDM", "6 GHz con OFDMA"], "802.11a definió OFDM en la banda de 5 GHz. ERP-OFDM es la versión de OFDM de 802.11g en 2.4 GHz, que es la confusión tentadora.", ["DSSS en 2.4 GHz describe 802.11 y 802.11b, no 802.11a.", null, "ERP-OFDM es el uso de OFDM de 802.11g en 2.4 GHz, una enmienda y una banda diferentes.", "OFDMA y 6 GHz llegaron con 802.11ax, mucho después de 802.11a."]],
  "x22": ["Un cliente envía una trama de datos a través de su AP a un servidor en la LAN cableada (To DS = 1, From DS = 0). ¿Qué dirección va en el campo Address 1 (receptor)?", ["La dirección MAC del servidor", "La dirección MAC del cliente", "La dirección IP del gateway predeterminado", "El BSSID del AP"], "Address 1 es la dirección del receptor, y el radio que recibe la trama por el aire es el AP, así que contiene el BSSID. La MAC del servidor es el destino final y va en Address 3.", ["La MAC del servidor es el destino final y va en Address 3 en una trama To DS.", "El cliente es el transmisor, así que su MAC está en Address 2, no en la dirección del receptor.", "Los encabezados 802.11 solo llevan direcciones MAC; las direcciones IP están dentro del payload.", null]],
  "x23": ["En un BSS con WPA2-Enterprise, una captura muestra dos tramas de autenticación Open System antes de la asociación. ¿Qué logran?", ["Son una formalidad; la autenticación real ocurre después de la asociación", "Verifican la contraseña del usuario con el servidor RADIUS", "Entregan la PMK del AP al cliente", "Derivan la GTK usada para el tráfico multicast"], "La autenticación Open System no realiza ninguna verificación de identidad; 802.1X/EAP y el 4-way handshake ocurren después de la asociación. No se contacta a RADIUS durante estas dos tramas.", [null, "Se contacta a RADIUS durante 802.1X después de la asociación, no durante las tramas Open System.", "La PMK proviene del intercambio EAP y nunca se envía por el aire en estas tramas.", "La GTK se entrega en el 4-way handshake, que ocurre después de la asociación y de EAP."]],
  "x24": ["Una captura muestra a un cliente enviando tramas null data con el bit Power Management en 1. ¿Qué está haciendo el cliente?", ["Pidiéndole al AP una tasa de datos más alta", "Haciendo roaming a otro BSS", "Avisándole al AP que va a entrar en ahorro de energía", "Enviando un mensaje keepalive al servidor RADIUS"], "Las tramas null data no llevan payload y se usan para señalar el estado de energía; el bit en 1 le indica al AP que guarde las tramas en buffer. Un roaming mostraría tramas de reasociación, no null data.", ["Las tasas de datos las elige la adaptación de tasa; las tramas null data no son solicitudes de tasa.", "Un roaming mostraría tramas de reasociación hacia un AP nuevo, no tramas null data hacia el actual.", null, "Los clientes nunca hablan directamente con el servidor RADIUS mediante tramas 802.11; el AP retransmite el EAP."]],
  "x25": ["La trama de una estación no recibe confirmación. ¿Cómo cambia DCF su siguiente backoff aleatorio?", ["Pone el backoff en cero y reintenta de inmediato", "Cambia a PCF y espera a que el access point la consulte", "Aproximadamente duplica su ventana de contención, hasta un máximo", "Espera al siguiente beacon DTIM para reintentar"], "Tras una transmisión fallida, la ventana de contención crece (backoff exponencial) hasta CWmax, lo que reduce la probabilidad de otra colisión. Reintentar con backoff cero haría más probables las colisiones repetidas.", ["Reintentar con backoff cero haría más probable otra colisión, así que DCF no lo hace.", "PCF es un modo opcional y poco usado; una trama fallida no hace que una estación cambie a él.", null, "La temporización DTIM rige la entrega del multicast en buffer, no la retransmisión unicast."]],
  "x26": ["Antes de transmitir, una estación verifica si el medio está ocupado detectando un preámbulo 802.11 decodificable o energía de RF en bruto. ¿Cómo se llama este mecanismo?", ["Clear channel assessment", "Network allocation vector", "Dynamic frequency selection", "Transmit power control"], "El clear channel assessment es la detección física de portadora mediante detección de señal y de energía. El NAV es la detección virtual de portadora, basada en los valores Duration de las tramas en lugar de en detectar RF.", [null, "El NAV es la detección virtual de portadora, que usa los valores Duration de las tramas, no la detección de energía de RF.", "DFS detecta radares y cambia de canal; no es la verificación del medio en cada trama.", "TPC ajusta la potencia de transmisión y no decide si el medio está ocupado."]],
  "x27": ["Un AP ERP debe proteger las tramas OFDM de las estaciones 802.11b cercanas. ¿Cuándo es RTS/CTS una mejor opción que CTS-to-self?", ["Cuando todas las estaciones se escuchan bien entre sí", "Cuando el objetivo es la menor sobrecarga posible", "Cuando no hay ninguna estación 802.11b presente", "Cuando algunas estaciones no pueden escuchar al emisor"], "Con RTS/CTS, el CTS del receptor llega a las estaciones que no pueden escuchar al emisor, lo que resuelve los nodos ocultos. CTS-to-self tiene menos sobrecarga, así que gana cuando la sobrecarga importa y todos pueden escuchar al emisor.", ["Cuando todos escuchan al emisor, CTS-to-self ya llega a todas las estaciones con menos sobrecarga.", "RTS/CTS agrega un intercambio de tramas adicional, así que no es la opción de menor sobrecarga.", "Sin estaciones 802.11b, la protección ERP normalmente no es necesaria en absoluto.", null]],
  "x28": ["Los teléfonos Wi-Fi deben ahorrar batería, pero seguir recibiendo tramas de voz con poco retraso. ¿Qué método permite que el teléfono envíe una trigger frame para obtener las tramas en buffer del AP?", ["PS-Poll legacy", "U-APSD (WMM Power Save)", "Entrega multicast por DTIM", "Spatial multiplexing power save"], "U-APSD permite que las propias tramas de subida de un cliente disparen la entrega de las tramas de bajada en buffer, lo que es adecuado para voz. El PS-Poll legacy obtiene solo una trama en buffer por consulta y agrega retraso.", ["El PS-Poll legacy obtiene una trama en buffer por consulta, lo que agrega retraso para la voz.", null, "La entrega por DTIM es para tramas broadcast y multicast en buffer, no para voz unicast disparada.", "SM power save apaga las cadenas de radio adicionales; no obtiene tramas en buffer."]],
  "x29": ["¿Qué categoría de acceso de WMM tiene la prioridad más baja para acceder al medio?", ["Voice", "Background", "Video", "Best effort"], "Background tiene el AIFS más largo y la ventana de contención más grande de las cuatro categorías de WMM. Best effort es la categoría predeterminada, pero sigue estando por encima de background.", ["Voice tiene la prioridad más alta, con el AIFS más corto y la ventana de contención más pequeña.", null, "Video es la segunda categoría de mayor prioridad, no la más baja.", "Best effort es la categoría predeterminada, pero igual tiene prioridad sobre background."]],
  "x30": ["¿Por qué la agregación A-MPDU aumenta el throughput en los radios 802.11n y posteriores?", ["Permite que varios clientes transmitan en el mismo instante", "Obliga al radio a usar 1024-QAM", "Elimina la necesidad de cualquier confirmación", "Muchas tramas comparten un período de contención y un preámbulo"], "La agregación envía muchas MPDU tras una sola contención y un solo preámbulo PHY, lo que reduce la sobrecarga por trama. La confirmación sigue siendo necesaria; solo que se hace con un Block Ack.", ["Atender a varios clientes a la vez es OFDMA o MU-MIMO; la agregación empaqueta tramas para un solo receptor.", "La agregación funciona con cualquier MCS y no obliga a una modulación en particular.", "Las tramas agregadas se siguen confirmando, usando un solo Block Ack.", null]],
  "x31": ["Un cliente se mueve entre dos AP que pertenecen al mismo ESS. ¿Qué trama envía al nuevo AP para unirse a él?", ["Reassociation request", "Probe response", "Disassociation", "Beacon"], "Al hacer roaming dentro de un ESS, el cliente envía una reassociation request al nuevo AP. Las probe responses y los beacons los envían los AP, no el cliente.", [null, "Las probe responses las envían los AP a los clientes durante el escaneo, no los clientes que hacen roaming.", "La desasociación termina una asociación; no es la forma en que un cliente se une al nuevo AP.", "Los beacons los transmiten los AP para anunciar un BSS, no los clientes."]],
  "x32": ["¿Por qué los clientes normalmente usan escaneo pasivo en los canales DFS de 5 GHz?", ["El escaneo pasivo siempre es más rápido que el activo", "Los beacons en canales DFS llevan la PMK de la red", "No deben transmitir allí hasta escuchar un AP", "Las probe requests están cifradas en los canales DFS"], "Los clientes no deben transmitir en un canal DFS hasta escuchar un AP operando allí, así que escuchan los beacons. El escaneo pasivo suele ser más lento, ya que el cliente debe esperar los beacons.", ["El escaneo pasivo suele ser más lento, porque el cliente debe esperar un beacon en cada canal.", "Los beacons nunca llevan la PMK; las claves se derivan durante la autenticación y el handshake.", null, "Las probe requests son tramas de gestión sin cifrar en todos los canales."]],
  "x33": ["La hoja de datos de un AP nuevo dice que necesita unos 40 W para funcionar por completo. ¿Qué estándar PoE debe soportar el puerto del switch?", ["802.3af", "802.3at", "802.3bt", "802.3ad"], "802.3at (PoE+) entrega hasta 25.5 W en el dispositivo, así que un AP de 40 W necesita 802.3bt. 802.3ad es agregación de enlaces y no tiene nada que ver con la energía.", ["802.3af entrega unos 12.95 W en el dispositivo, muy por debajo de 40 W.", "802.3at (PoE+) entrega hasta 25.5 W en el dispositivo, todavía por debajo de 40 W.", null, "802.3ad es agregación de enlaces y no tiene nada que ver con Power over Ethernet."]],
  "x34": ["Un aula tendrá 60 estudiantes transmitiendo video al mismo tiempo. ¿Qué tipo de requisito determinará principalmente la cantidad de AP?", ["Requisitos de capacidad", "Requisitos de cobertura", "El dominio regulatorio", "La longitud de los tendidos de cable"], "Muchos usuarios intensivos simultáneos hacen que el tiempo de aire sea el límite, así que la cantidad de AP la determina la capacidad. Un solo AP puede cubrir un aula, así que diseñar solo por cobertura se quedaría corto.", [null, "Un AP podría cubrir un aula, así que diseñar solo por cobertura dejaría muy poco tiempo de aire para 60 transmisiones.", "El dominio regulatorio define los canales y la potencia permitidos, no cuántos AP necesitan los usuarios.", "La longitud del cable limita dónde pueden ir los AP, pero no decide cuántos se necesitan."]],
  "x35": ["Un centro de conferencias con muchos AP debe obtener la mayor capacidad total posible en 5 GHz. ¿Qué ancho de canal suele ser el MEJOR?", ["160 MHz en cada AP para las tasas más altas por cliente", "80 MHz en cada AP para que cada celda sea más rápida", "40 MHz en 2.4 GHz y 80 MHz en 5 GHz", "20 MHz, para tener más canales que reutilizar"], "Los canales estrechos dan más canales sin superposición, lo que reduce la contención cocanal, que es lo que más importa en diseños densos. Los canales anchos aumentan la tasa máxima de un cliente, pero obligan a los AP a compartir canales.", ["160 MHz deja muy pocos canales, así que los AP cercanos los compartirían y competirían por el tiempo de aire.", "80 MHz sigue limitando la reutilización en un espacio denso y aumenta la contención cocanal.", "40 MHz en 2.4 GHz no deja reutilización limpia de canales y es una mala práctica en espacios densos.", null]],
  "x36": ["Un cliente antiguo conectado a una tasa de datos muy baja ralentiza a todos los demás clientes de su AP. ¿Por qué?", ["Obliga a todos los demás clientes a usar su propio ancho de canal", "Necesita mucho más tiempo de aire para enviar los mismos datos", "Deshabilita WMM para todo el BSS", "Hace que el AP baje su potencia de transmisión"], "El tiempo de aire es compartido, y un cliente lento ocupa el medio mucho más tiempo por byte, lo que deja menos tiempo para los demás. El ancho de canal se define por BSS y no lo dicta un solo cliente.", ["El ancho de canal lo define el AP para el BSS; no lo dicta un cliente lento.", null, "WMM sigue habilitado en el BSS sin importar la tasa de datos de un cliente.", "Los AP no bajan su potencia de transmisión porque se asocie un cliente lento."]],
  "x37": ["En un estadio, los diseñadores montan antenas patch orientadas hacia abajo en lugar de omnidireccionales. ¿Cuál es la razón principal?", ["Las antenas patch no necesitan PoE", "Forman celdas pequeñas para poder reutilizar más los canales", "Las antenas omnidireccionales no funcionan en 5 GHz", "Las antenas patch aumentan el límite legal de EIRP"], "Las antenas direccionales limitan cada celda a una sección de asientos, así que los mismos canales se pueden reutilizar cerca. Los límites de EIRP los fija la regulación y no aumentan por la elección de antena.", ["Las antenas patch usadas con AP igual necesitan energía para el AP; el tipo de antena no elimina la necesidad de PoE.", null, "Las antenas omnidireccionales funcionan bien en 5 GHz; el problema es que su patrón amplio limita la reutilización.", "Los límites de EIRP los fijan los reguladores y no aumentan por elegir una antena patch."]],
  "x38": ["En una WLAN basada en controlador, compartir claves en caché y coordinar los roamings entre AP pertenece a ¿qué plano?", ["Plano de gestión", "Plano de datos", "Plano de usuario", "Plano de control"], "La coordinación entre dispositivos, como el soporte de roaming, el caché de claves y RRM, es trabajo del plano de control. El plano de gestión es la configuración y el monitoreo por parte de los administradores.", ["El plano de gestión abarca la configuración y el monitoreo por parte de los administradores, no la coordinación entre dispositivos.", "El plano de datos reenvía el tráfico de usuarios; la coordinación del roaming es una función de control separada.", "El plano de usuario es otro nombre del plano de datos, que solo mueve tráfico de usuarios.", null]],
  "x39": ["En una WLAN administrada desde la nube, falla el enlace a internet del sitio hacia el servicio en la nube. ¿Qué suele pasar con los clientes que ya están conectados?", ["Siguen funcionando, ya que los AP reenvían el tráfico localmente", "Se desconectan, porque el plano de datos está en la nube", "Solo pueden llegar al dashboard en la nube", "Pasan automáticamente a un enlace mesh"], "Los diseños administrados desde la nube mantienen el plano de datos en el AP, así que el tráfico local sigue fluyendo; se pierden principalmente la gestión y las funciones que dependen de la nube. Los datos de los usuarios no pasan por el servicio en la nube.", [null, "En los diseños administrados desde la nube, los AP reenvían el tráfico de usuarios localmente, no a través de la nube.", "El dashboard es justamente lo que se vuelve inaccesible cuando falla el enlace a internet.", "Mesh es una función separada que debe diseñarse; no es un respaldo ante la pérdida de conexión con la nube."]],
  "x40": ["En un auditorio con cuatro AP, el AP cerca de la puerta tiene la mayoría de los clientes mientras los demás están inactivos. ¿Qué función resuelve esto?", ["Band steering", "Dynamic Frequency Selection", "Balanceo de carga entre AP", "BSS coloring"], "El balanceo de carga reparte los clientes entre los AP que pueden atenderlos. El band steering mueve clientes entre bandas del mismo AP, lo que no corrige un reparto desigual entre AP.", ["El band steering mueve clientes entre bandas del mismo AP, no entre AP.", "DFS se encarga de evitar radares en 5 GHz y no tiene ningún papel en balancear clientes.", null, "BSS coloring ayuda a la reutilización espacial en canales compartidos y no mueve clientes."]],
  "x41": ["Un diseñador quiere un solo SSID 802.1X en lugar de SSID separados para personal, contratistas e IoT, pero cada grupo debe quedar en su propia VLAN. ¿Cómo se logra?", ["Poner cada grupo de usuarios en su propio canal", "Usar filtrado MAC en el AP", "Hacer que RADIUS devuelva una VLAN para cada usuario", "Ocultar el SSID para cada grupo"], "RADIUS puede devolver un atributo de VLAN después de la autenticación, lo que coloca a los usuarios en VLAN distintas dentro de un solo SSID y reduce la sobrecarga de SSID. El filtrado MAC solo permite o bloquea dispositivos y no asigna VLAN.", ["Los canales son una propiedad de RF de los AP; poner grupos en canales diferentes no asigna VLAN.", "El filtrado MAC solo permite o bloquea dispositivos y no puede elegir una VLAN.", null, "Ocultar el SSID solo lo quita de los beacons; no puede separar grupos en VLAN."]],
  "x42": ["Un AP de tres radios necesita más energía de la que puede entregar el puerto 802.3at del switch. ¿Qué suele pasar?", ["Puede funcionar en un modo reducido, por ejemplo con menos cadenas de radio", "Consume la energía adicional y daña el switch", "Toma energía de un segundo puerto del switch automáticamente", "Deshabilita WPA3 hasta que haya más energía disponible"], "Muchos AP detectan la clase de energía disponible y deshabilitan funciones como cadenas de radio o puertos. La negociación PoE impide que un dispositivo simplemente consuma más de lo que ofrece el puerto.", [null, "La negociación PoE limita la energía a lo que ofrece el puerto, así que el AP no puede simplemente consumir de más.", "Los AP no combinan automáticamente la energía de otro puerto a menos que estén diseñados y cableados específicamente para ello.", "El presupuesto PoE no tiene ninguna relación con los protocolos de seguridad que soporta el AP."]],
  "x43": ["¿Por qué se considera que WEP está roto?", ["Usaba AES con una clave demasiado corta", "Requería un servidor RADIUS para funcionar", "Solo podía usarse en 2.4 GHz", "RC4 con un IV corto y reutilizado permite a los atacantes recuperar la clave"], "WEP usaba RC4 con un IV de 24 bits que se repite, así que el tráfico capturado permite a los atacantes recuperar la clave. WEP nunca usó AES; AES llegó con CCMP en WPA2.", ["WEP usaba RC4, no AES; AES llegó con CCMP en WPA2.", "WEP usaba claves compartidas estáticas y no requería RADIUS.", "WEP podía usarse en cualquier banda; su debilidad era criptográfica, no relacionada con la banda.", null]],
  "x44": ["Una empresa habilita el modo de transición de WPA3-Personal para que los dispositivos antiguos puedan seguir uniéndose. ¿Cuál es la principal contrapartida de seguridad?", ["Los dispositivos WPA3 deben recurrir a TKIP", "Los clientes pueden ser degradados a WPA2-PSK y sus riesgos", "PMF se desactiva para todos los dispositivos", "La passphrase debe volverse más corta"], "El modo de transición sigue aceptando WPA2-PSK, así que un atacante puede empujar a los clientes a WPA2 y capturar un handshake para adivinar la clave offline. TKIP no forma parte del modo de transición de WPA3.", ["WPA3 no usa TKIP; el modo de transición permite WPA2 con CCMP, no TKIP.", null, "PMF es obligatorio para los clientes WPA3 y opcional para los clientes WPA2 en modo de transición; no se desactiva para todos.", "El modo de transición no obliga a usar una passphrase más corta; la misma passphrase funciona para ambos métodos."]],
  "x45": ["¿Qué clave cifra las tramas broadcast y multicast en un BSS con WPA2?", ["PTK", "GTK", "PMK", "PSK"], "La Group Temporal Key protege las tramas broadcast y multicast y la comparten todas las estaciones del BSS. La PTK es única para cada cliente y protege sus tramas unicast.", ["La PTK es única para cada cliente y protege el tráfico unicast de ese cliente.", null, "La PMK es la clave raíz usada para derivar la PTK; no cifra tramas directamente.", "La PSK es el secreto configurado basado en la passphrase, no la clave de cifrado de tramas para el tráfico de grupo."]],
  "x46": ["Unas laptops usan PEAP-MSCHAPv2, pero están configuradas para no validar el certificado del servidor. ¿Qué riesgo crea esto?", ["Se omite el 4-way handshake, así que nunca se deriva ninguna PTK ni GTK", "Los clientes recurren al cifrado WEP", "El AP ya no puede asignar VLAN", "Un evil twin con un servidor RADIUS falso puede capturar credenciales"], "Sin validar el certificado del servidor, un cliente ejecutará PEAP con un impostor, lo que expone el intercambio MSCHAPv2 interno a ser descifrado offline. El 4-way handshake sigue ocurriendo después de que EAP tiene éxito.", ["El 4-way handshake sigue ejecutándose después de EAP; omitir la verificación del certificado no lo elimina.", "Los clientes no recurren a WEP; la debilidad es confiar en cualquier servidor durante EAP.", "La asignación de VLAN desde RADIUS no se ve afectada por si los clientes validan o no el certificado.", null]],
  "x47": ["El SSID de invitados de un hotel usa un portal cautivo, pero sin cifrado Wi-Fi. ¿Qué proporciona el portal?", ["Inicio de sesión o aceptación de términos, no cifrado", "Cifrado AES de todo el tráfico de invitados", "Autenticación mutua por certificados", "Protección contra AP evil twin"], "Un portal cautivo controla el acceso en la capa web; el enlace aéreo sigue abierto a menos que se agregue OWE o WPA. No cifra las tramas, que es la idea errónea más tentadora.", [null, "Un portal cautivo funciona en la capa web y no agrega cifrado Wi-Fi; se necesitaría OWE o WPA.", "La autenticación mutua por certificados es EAP-TLS, que un portal web no proporciona.", "Un atacante puede clonar un SSID abierto y la página de su portal, así que no ofrece protección contra evil twins."]],
  "x48": ["Una organización quiere un método EAP con túnel que necesite solo un certificado de servidor y pueda transportar métodos internos legacy como PAP. ¿Cuál es adecuado?", ["EAP-TLS", "LEAP", "EAP-TTLS", "EAP-MD5"], "EAP-TTLS crea un túnel TLS con un certificado de servidor y puede transportar muchos métodos internos, incluido PAP. EAP-TLS también necesita un certificado de cliente y no transporta ningún método interno de contraseña.", ["EAP-TLS requiere certificados de cliente y no transporta un método interno de contraseña como PAP.", "LEAP es un método legacy sin túnel TLS y con debilidades conocidas.", null, "EAP-MD5 no tiene túnel ni certificado de servidor, y no ofrece autenticación mutua."]],
  "x49": ["Un ingeniero quiere ver cómo cambia con el tiempo la energía de un interferente a lo largo de la banda. ¿Qué vista del analizador de espectro es la MÁS adecuada?", ["El gráfico FFT en tiempo real", "El indicador de ciclo de trabajo", "La vista waterfall (espectrograma)", "La tabla de utilización del canal"], "Un waterfall grafica la frecuencia contra el tiempo con colores para la amplitud, lo que muestra cómo cambia la energía. La FFT en tiempo real muestra solo el barrido actual, no el historial.", ["La FFT en tiempo real muestra solo el barrido actual, no cómo cambia la energía con el tiempo.", "Un indicador de ciclo de trabajo da un porcentaje de tiempo ocupado, no un historial en el tiempo a través de las frecuencias.", null, "Las tablas de utilización del canal resumen el uso del tiempo de aire, no la forma de un interferente a lo largo del tiempo."]],
  "x50": ["Un analizador de espectro muestra ráfagas estrechas que saltan rápidamente por toda la banda de 2.4 GHz. ¿Cuál es la fuente MÁS probable?", ["Un dispositivo Bluetooth", "Un horno de microondas", "Un AP 802.11 en el canal 6", "Un radar meteorológico de 5 GHz"], "Bluetooth usa canales estrechos y salto de frecuencia en toda la banda de 2.4 GHz. Un horno de microondas produce una señal amplia en una parte fija de la banda en lugar de saltar.", [null, "Un horno de microondas produce energía amplia en una región fija de la banda en lugar de saltos estrechos.", "Un AP en el canal 6 se queda en un canal de 20 MHz y no salta por la banda.", "El radar meteorológico opera en 5 GHz y no aparecería en una vista de 2.4 GHz."]],
  "x51": ["Una vista de espectro muestra una señal amplia y pulsante en la parte superior de la banda de 2.4 GHz que aparece solo a la hora del almuerzo cerca de la sala de descanso. ¿Cuál es la fuente MÁS probable?", ["Unos audífonos Bluetooth", "Un AP 802.11ax", "Un teléfono inalámbrico de 5 GHz", "Un horno de microondas"], "Los hornos de microondas filtran energía amplia y pulsada centrada alrededor de 2.45 GHz, lo que coincide con el horario y la ubicación. Bluetooth aparecería como saltos estrechos por toda la banda.", ["Bluetooth aparece como saltos estrechos por toda la banda, no como una señal amplia y pulsada cerca de un extremo.", "Un AP 802.11ax muestra formas estables de canal OFDM, no ráfagas ligadas a un electrodoméstico.", "Un teléfono de 5 GHz no aparecería en absoluto en una vista de espectro de 2.4 GHz.", null]],
  "x52": ["Un ingeniero debe capturar el roaming de un teléfono entre AP en los canales 1 y 11. ¿Qué configuración de captura funciona MEJOR?", ["Un adaptador fijo solo en el canal 1", "Un adaptador en modo monitor por canal, capturando juntos", "Una captura cableada en el puerto uplink de un AP", "Un adaptador en modo managed unido al SSID"], "Un roaming abarca dos canales, así que un adaptador en modo monitor en cada uno captura ambos lados a la vez. Una captura cableada del uplink no ve en absoluto las tramas de gestión 802.11.", ["Un solo adaptador en el canal 1 se pierde todo lo que ocurre después de que el teléfono pasa al canal 11.", null, "Una captura cableada del uplink nunca ve tramas de gestión 802.11 como la reasociación.", "En modo managed, el adaptador captura solo su propio tráfico, no las tramas del teléfono."]],
  "x53": ["Un diseño para voz tiene como objetivo 25 dB de SNR. En un punto, la señal es de -70 dBm y el piso de ruido es de -90 dBm. ¿Qué debe decir el informe?", ["Cumple el objetivo con 5 dB de sobra", "Queda 5 dB por debajo del objetivo", "Cumple el objetivo exactamente", "La SNR no se puede calcular con estos valores"], "La SNR es la señal menos el ruido: -70 - (-90) = 20 dB, que está 5 dB por debajo del objetivo. Suponer que una señal de -70 dBm es automáticamente suficiente para voz ignora el piso de ruido.", ["La señal menos el ruido es 20 dB, que está por debajo del objetivo de 25 dB, no por encima.", null, "20 dB y 25 dB difieren en 5 dB, así que el objetivo no se cumple exactamente.", "La SNR es simplemente la señal menos el ruido en dB, y se dan ambos valores."]],
  "x54": ["Solo un modelo de laptop se desconecta con frecuencia; los demás dispositivos en el mismo lugar funcionan bien. ¿Cuál es el MEJOR primer paso?", ["Subir la potencia de transmisión de todos los AP en esa área del edificio", "Mover todos los AP a un canal nuevo", "Reemplazar el certificado del servidor RADIUS", "Revisar y actualizar el driver Wi-Fi de ese modelo"], "Un problema limitado a un modelo apunta al lado del cliente, y los drivers desactualizados son una causa común. Cambiar la potencia o los canales de los AP afecta a todos e ignora la evidencia de que los demás funcionan bien.", ["Subir la potencia de todos los AP afecta a todos e ignora que los demás dispositivos en el mismo lugar funcionan bien.", "Cambiar el canal de todos los AP es un cambio amplio sin evidencia de que el canal sea la causa.", "Un problema de certificado afectaría a todos los clientes 802.1X, no a un modelo que se desconecta de forma intermitente.", null]],
  "x55": ["Dos AP en salas adyacentes están ambos en el canal 36 de 5 GHz a 20 MHz y se escuchan claramente. ¿Qué problema causa esto?", ["Contención cocanal", "Interferencia de canal adyacente", "Colisiones por nodo oculto", "Desajuste de polarización"], "Los AP en el mismo canal que se escuchan entre sí deben compartir el tiempo de aire, lo que es contención cocanal. La interferencia de canal adyacente involucra canales distintos pero superpuestos.", [null, "La interferencia de canal adyacente requiere canales distintos pero superpuestos; estos AP comparten un mismo canal.", "Los nodos ocultos no pueden escucharse entre sí, mientras que estos AP se escuchan claramente.", "El desajuste de polarización tiene que ver con la orientación de las antenas y no explica que dos AP compartan el tiempo de aire."]],
  "x56": ["Los clientes en extremos opuestos de una sala grande no pueden escucharse y colisionan en el AP. ¿Qué cambio elimina la causa de fondo?", ["Usar un intervalo DTIM más largo", "Ensanchar el canal del AP", "Agregar o mover AP para que los clientes de cada celda se escuchen entre sí", "Ocultar el SSID en los beacons"], "Los nodos ocultos existen porque los clientes están demasiado lejos para detectarse entre sí; las celdas más pequeñas lo corrigen. Un intervalo DTIM más largo solo afecta el ahorro de energía y la entrega multicast.", ["DTIM afecta el multicast en buffer y el ahorro de energía, no si los clientes pueden escucharse entre sí.", "Un canal más ancho no hace que los clientes lejanos se escuchen entre sí y puede reducir la reutilización.", null, "Ocultar el SSID solo cambia los beacons y no hace nada para que los clientes se escuchen entre sí."]],
  "x57": ["Un ingeniero corrigió un problema recurrente de roaming. En un proceso estructurado de resolución de problemas, ¿qué debe ir al final?", ["Deshacer la corrección para demostrar que fue lo que causó la mejora", "Cerrar el ticket sin ninguna nota", "Documentar el problema, la causa, la corrección y los resultados", "Reiniciar todos los AP por seguridad"], "Documentar los hallazgos ayuda en futuras resoluciones de problemas y confirma la solución. Deshacer una corrección que funciona volvería a causar la falla a los usuarios sin aportar valor.", ["Deshacer una corrección que funciona vuelve a causar la falla a los usuarios y no es un paso final estándar.", "Cerrar sin notas pierde lo aprendido y hace más difícil resolver una repetición.", null, "Reiniciar todos los AP interrumpe a los usuarios y no aporta nada una vez resuelto el problema."]],
  "x58": ["Durante un survey de validación, un área muestra una señal de -65 dBm con un piso de ruido de -80 dBm. ¿Qué debe reportar el ingeniero?", ["SNR deficiente (15 dB) a pesar de la buena señal", "Condiciones excelentes para llamadas de voz", "La potencia de transmisión del AP es demasiado alta", "Contención cocanal por demasiados SSID"], "El nivel de señal se ve bien, pero un piso de ruido elevado deja solo 15 dB de SNR, lo que es demasiado bajo para voz y apunta a interferencia. Juzgar solo por la señal llevaría a calificarlo erróneamente como excelente.", [null, "15 dB de SNR es demasiado bajo para voz, así que las condiciones no son excelentes a pesar de la buena señal.", "Una potencia alta del AP subiría la señal, no el piso de ruido; el ruido apunta a interferencia.", "La sobrecarga de SSID aumenta la utilización del canal; no eleva el piso de ruido medido."]],
  "x59": ["¿Qué mide un survey activo que un survey pasivo no mide?", ["La intensidad de señal de los beacons de cada AP", "El piso de ruido en cada canal", "La lista de SSID cercanos", "El rendimiento del cliente asociado, como el throughput"], "Un survey activo se asocia a la red y mide throughput, reintentos, pérdida y roaming. La intensidad de señal de los beacons también la recopilan los surveys pasivos.", ["Los surveys pasivos también registran la señal de los beacons de cada AP que escuchan.", "El piso de ruido se mide en los surveys pasivos y en el análisis de espectro, no solo en los surveys activos.", "Cualquier escaneo pasivo enumera los SSID cercanos.", null]],
  "x60": ["Los clientes de un SSID nuevo reciben direcciones IP de la subred equivocada. ¿Qué se debe revisar PRIMERO?", ["La ganancia de la antena del AP", "La asignación de SSID a VLAN y las VLAN del trunk", "El intervalo DTIM del AP", "La fecha de vencimiento del certificado RADIUS"], "Una subred equivocada significa que el SSID está conectado a la VLAN incorrecta o que el trunk del switch no transporta la VLAN correcta. Un problema con el certificado RADIUS detendría la autenticación, no entregaría la subred equivocada.", ["La ganancia de la antena cambia la cobertura de RF, no la subred que asigna DHCP.", null, "DTIM afecta la temporización del ahorro de energía y no tiene nada que ver con el direccionamiento IP.", "Un certificado RADIUS vencido detendría la autenticación en lugar de entregar la subred equivocada."]]
});
